INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at") OVERRIDING SYSTEM VALUE VALUES (873, 44, 3, 2, 2, '召鸭的时候，撞见老熟人下海，是什么样的感觉？

黎泱在东南亚最top的会所二楼往下看，看到她那位有着严重洁癖的——

前·性爱·搭子。

架着墨镜，慵懒地坐在沙发上，白色衬衣的领口微微敞开，怀里抱着一只矜贵的布偶猫。

“他一看，活就很好。”赵雅琳顺着黎泱的目光说道。

“嗯哼~”

黎泱倚在二楼的栏杆，目光扫过男人的喉结，来到……。

他这个人嘛，确实挺能干的。

黎泱对赵雅琳的话，表示认同。

赵雅琳：“怎样泱泱？有感觉吗？有没有标题……”

“没有。”黎泱收回了目光，在旁边的花瓶里抽出了一株粉色的芍药。

“黎小姐……”赵雅琳端了起来，“作为你性功能障碍的主治医生，我劝你放下前男友，别在一棵树上吊死！”

她顿了顿，补充一句:

“林子大了，什么鸟都要试试！”

“首先我再次声明，本人母胎单身，不存在前男友，另外……”黎泱笑着说:

“你这位赵大医生，就算怕我砸了你的招牌，也不能把我推给一个瞎子吧？”

“瞎，瞎子？”赵雅琳不解：“人家不就戴个墨镜，怎么就……”

话没说完，那男人的布偶猫从他身上窜逃。身旁的人立刻上前搀扶，领着他往前走。

赵雅琳讶然:“残障人士也下海？现在经济下行成这样了吗？”

黎泱把芍药放在鼻尖闻了闻，笑道:

“他也有可能是装瞎，不是真的瞎。”

赵雅琳不屑:“呵，在夜店装B的男人我见多了，装瞎的我从未……”

话再次被打断，只见黎泱把手里的芍药伸出栏杆之外，毫无预兆地松开指尖……

刚好经过的男人突然顿住了脚步，手一抬，稳稳当当地接住从天而降的芍药。

一片花瓣从他节骨分明的手中掉落。

“你看，这男人是不是连B都不如？”黎泱托着下巴看向赵雅楠，笑得比她扔掉的芍药更灿烂。

赵雅琳不敢肯定，但她觉得黎泱在骂人，骂得还有点脏，像有很多仇怨。

娇艳的芍药盛开在泰诺·帕恩的手里，他仰头，缓缓摘下了墨镜。

那双异于常人的褐灰色眼眸，看向二楼栏杆处的黎泱。

久违的一张脸。

他说过，只给她一次离开的机会。

可这个女人消失三年，如今再次出现在缅城。

而缅城，如今已经是他泰诺·帕恩的地盘。

掌心渐拢，他揉碎了那朵从天而降的花。

站在楼上的黎泱，坦然地迎上男人的目光，似笑非笑。

鼓风机撩起她的卷发，舞台光影刚好掠过她的脸。

一切时机都刚刚好，穿着红裙的她美得不可方物。

一对男女在迷幻的灯光下，四目相对。

眸光像有钩子，勾出身体里早就纠缠不清的荷尔蒙。

成年男女，床笫之欢。

一拍即合，一啪即散。

穿上内裤，大家挥挥手都当个体面的人。

在性事方面，黎泱自认洒脱。

但分开的这些年，每当夜深人静的时候，她都会想起两人的过往。

想起男人这张曾经让自己欲仙欲死的皮囊。

可这副完美的皮囊下，全是烂透了的果子。

这时，她就忍不住会在想。如果日后再见，她一定揪着这个男人问个明白:

……

……

……

你这臭不要脸的瞎子，到底是从什么时候开始看得见的？？！', 1120, 'rule', FALSE, 'selected', 4.0, '该场景在有限篇幅内通过对话、动作和内心独白高效建立人物关系、制造悬念并完成反转；扔花接花的动作设计将“装瞎”信息视觉化，配角误解烘托主角，对白节奏明快，情绪从调侃转向张力，具有可迁移的场景构建与信息揭露技巧。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 3.5, "distinctiveness": 3.5, "prose_quality": 3.5, "reference_value": 4.0, "scene_completeness": 4.0, "technique_value": 4.0}, "reference_reason": "该场景在有限篇幅内通过对话、动作和内心独白高效建立人物关系、制造悬念并完成反转；扔花接花的动作设计将“装瞎”信息视觉化，配角误解烘托主角，对白节奏明快，情绪从调侃转向张力，具有可迁移的场景构建与信息揭露技巧。", "reference_score": 4.0, "reference_status": "selected"}'::jsonb, '黎泱在东南亚会所二楼与医生赵雅琳闲聊，撞见前性爱搭子泰诺·帕恩装瞎下海。她扔下芍药试探，他接住并摘下墨镜，两人对视。黎泱内心翻涌，想起过往，最后质问这瞎子何时开始看得见。', '以对话和动作推进，用芍药试探、装瞎反转制造张力，节奏明快，语言俏皮带刺，内心独白收尾，适合学习如何用细节和反转写重逢。', '适合参考用道具和动作揭示人物关系与秘密，避免过度解释内心，保持对话节奏和留白。', ARRAY['romance', 'dialogue_conflict', 'mystery']::text[], ARRAY['romance', 'dialogue_conflict', 'mystery']::text[], ARRAY['contrast', 'foreshadow', 'hook', 'twist']::text[], ARRAY['contrast', 'foreshadow', 'hook', 'twist']::text[], ARRAY['cinematic', 'colloquial', 'fast_paced', 'humorous']::text[], ARRAY['cinematic', 'colloquial', 'fast_paced', 'humorous']::text[], ARRAY['tension', 'heartache', 'excitement']::text[], ARRAY['tension', 'heartache', 'excitement']::text[], ARRAY['light', 'neon', 'night']::text[], ARRAY['light', 'neon', 'night']::text[], 'advance', '{"emotion_tags": ["tension", "heartache", "excitement"], "key_images": ["light", "neon", "night"], "narrative_func": "advance", "scene_type": ["romance", "dialogue_conflict", "mystery"], "style_summary": "以对话和动作推进，用芍药试探、装瞎反转制造张力，节奏明快，语言俏皮带刺，内心独白收尾，适合学习如何用细节和反转写重逢。", "style_tags": ["cinematic", "colloquial", "fast_paced", "humorous"], "summary": "黎泱在东南亚会所二楼与医生赵雅琳闲聊，撞见前性爱搭子泰诺·帕恩装瞎下海。她扔下芍药试探，他接住并摘下墨镜，两人对视。黎泱内心翻涌，想起过往，最后质问这瞎子何时开始看得见。", "technique": ["contrast", "foreshadow", "hook", "twist"], "usage_hint": "适合参考用道具和动作揭示人物关系与秘密，避免过度解释内心，保持对话节奏和留白。"}'::jsonb, 'annotated', 'indexed', NULL, 1, TRUE, '2026-10-01T07:15:24.455781+00:00', '2026-10-01T08:01:42.585516+00:00');
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at") OVERRIDING SYSTEM VALUE VALUES (893, 44, 23, 15, 15, '第14章 给这本书打一个五星好评

失眠时，黎泱打开番茄APP看了一本小说。

男主和女主都是处，彼此的第一次。

可剧情进行到一半，男主那恶毒的妈给男主送来两个女人。男主把持不住脏了一次又一次。

于是女主把他一脚踹开，男二上位。

黎泱反手就给这本书打了一个五星好评，这是她作为高素质读者一贯的基操。

她能接受“男洁，女洁”；

也能接受“男不洁、女不洁”；

更能接受“男洁、女不洁”；

但！

不能接受“男不洁、女洁”。

无关对错，个人癖好而已。

点了一下手机屏幕右上方，她看到自己阅读时长超过30分钟后，才给出一个可以统计进去的五星书评。

黎泱才放下手机，安安稳稳地睡去。

她还美滋滋地做了个美梦，因为好人有好报。', 289, 'chapter_start', FALSE, 'archived', 2.8, '该场景完整、独立，语言流畅且带有网文特有的幽默吐槽，但整体属于日常人物性格展示片段，缺乏高迁移价值的叙事技巧或结构设计。其内心独白、列举偏好和反讽结尾虽有一定可借鉴性，但过于简单常见，不足以作为写作参考库的精选范例。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 4.0, "distinctiveness": 2.5, "prose_quality": 3.0, "reference_value": 2.5, "scene_completeness": 4.0, "technique_value": 2.5}, "reference_reason": "该场景完整、独立，语言流畅且带有网文特有的幽默吐槽，但整体属于日常人物性格展示片段，缺乏高迁移价值的叙事技巧或结构设计。其内心独白、列举偏好和反讽结尾虽有一定可借鉴性，但过于简单常见，不足以作为写作参考库的精选范例。", "reference_score": 2.8, "reference_status": "archived"}'::jsonb, '', '', '', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], '', '{}'::jsonb, 'not_applicable', 'not_applicable', NULL, 1, TRUE, '2026-10-01T07:15:24.455781+00:00', '2026-10-01T08:01:42.585516+00:00');
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at") OVERRIDING SYSTEM VALUE VALUES (885, 44, 15, 9, 9, '第8章 人生的癫疯

缅城的六月，燥热难当。午后的蝉鸣吵得人脑壳疼。

黎泱在庄园后院的空地上，拿着短刀，一下扎进眼前的稻草人。

699。

头顶毒辣的太阳，晒得她两颊通红，厚重的妆容糊了自己一脸。

两鬓的头发散了下来，被汗水黏在脸上。

这人不人，鬼不鬼的。颜值首次突破了自己人生的癫疯。

想到这里，她又哀怨地捅了稻草人一刀。

698。

她被泰诺丢到这里已经半个月了，都怪自己那日的那张嘴。

原本，在“杀人”和“放火”里，她选了后者。

因为胡建明给她的《论一个卧底的自我修养》，她只看了一半。不确定在卧底期间杀人要负什么责任，干脆挑“放火”这个简单亿点点的。

可泰诺问她为什么，她就嘴抽了，随便搪塞一句“不会用刀”……

结果，泰诺就派了阿义来教导她如何使用刀具。

“都说了，拇指不能压在刀背上。”阿义站在不远处的树荫下，皱着眉，朝黎泱嚷嚷。

在烈日下暴晒的黎泱压了压嘴角，拇指挪开，又插了稻草人一刀。

697。

当年在警校，警械使用课程满分的黎泱，没想到自己还会有回炉重造的一天。

“你是我带过最差的一个学生！”阿义站在50米开外的地方喊道。

“刀尖不够直！垂直插入，一刀毙命！你能不能用点心，不要辜负老板对你的期待，还有六百九十六次……”

阿义双手背在身后，皱着眉，频频摇头。

他真不懂自己老板看上这个女人什么了。自己跟了老板几年，连老板的手指头都碰不得，这个女人却能把老板生吃了……

黎泱又刺了一刀，刀尖擦过草人的肩膀，划破一条口子。

“偏了。”阿义冷声纠正，“再加两百次。898。”

“那也是895！”黎泱抗议，可阿义假装没听到，无动于衷。

黎泱咬紧了后牙槽。

她知道阿义在公报私仇。

巧了，她黎泱最会的，就是私报公仇。

所以一入夜，她就来到泰诺卧室。

刚洗完澡，头发还没擦干，湿漉漉的头发随意披散开来。

她穿着紧身背心小短裙。本意只是露出晒掉皮的胳膊和腿来卖惨，并没有别的意思。

真的。

没有勾引的意思。

真的。

而泰诺则穿着一件黑色背心，外面套了一件花色开衫，褐灰色的眼眸和干净利落的五官，让他多了几分像混血的美。

他坐在窗边，戴着耳机，怀里没有猫，瞳孔失焦地落在窗外漆黑的花园里。

月色朗朗，打在他半边的脸上。

失去了视觉，他从小就训练另外的四感。

所以黎泱刚来到他身后，泰诺就闻到熟悉的气味。

她没有喷香水的习惯，但身上的沐浴露带着一股淡淡的奶香味。

“这么晚还不休息？”

泰诺扯下了一边的耳塞，舒展了一条胳膊，搭在窗沿，给出黎泱滑入他怀里的空间。

果然，黎泱很自觉地靠近，曲着腿，整个人蜷缩在泰诺的怀里。

那股很淡的味道悄悄潜入鼻腔，却甜得发腻。

他对这个女人，真的有种生理性的喜欢。', 1052, 'chapter_start', FALSE, 'selected', 3.5, '该场景在有限篇幅内完成了从白天训练到夜晚暧昧的完整推进，对白节奏明快，冲突设计（阿义公报私仇/黎泱私报公仇）有张力，计数递减制造节奏与幽默，嗅觉描写有效表现失明角色的感知方式，心理重复强化人物性格，暧昧氛围控制得当。虽依赖前文设定且桥段常见，但上述技法具有可迁移性，适合作为写作参考。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 2.5, "distinctiveness": 3.0, "prose_quality": 3.0, "reference_value": 3.5, "scene_completeness": 4.0, "technique_value": 3.5}, "reference_reason": "该场景在有限篇幅内完成了从白天训练到夜晚暧昧的完整推进，对白节奏明快，冲突设计（阿义公报私仇/黎泱私报公仇）有张力，计数递减制造节奏与幽默，嗅觉描写有效表现失明角色的感知方式，心理重复强化人物性格，暧昧氛围控制得当。虽依赖前文设定且桥段常见，但上述技法具有可迁移性，适合作为写作参考。", "reference_score": 3.5, "reference_status": "selected"}'::jsonb, '黎泱被泰诺丢到庄园半月，因嘴硬说不会用刀，被阿义监督在烈日下练刀，反复刺稻草人，阿义公报私仇加练。入夜她穿背心短裙去泰诺卧室卖惨，泰诺在窗边闻到她气味，让她蜷进怀里，对她有生理性喜欢。', '烈日练刀与夜晚卧室冷暖对比，内心吐槽与感官细节交织，把训练苦闷、人物关系暧昧与喜剧感自然融合，节奏张弛有度，结尾以生理性喜欢点破情感张力。', '适合参考日常训练与暧昧场景的冷暖切换、内心独白与感官细节；避免卖惨与勾引边界模糊导致人物动机不清。', ARRAY['daily_life', 'romance', 'dialogue_conflict']::text[], ARRAY['daily_life', 'romance', 'dialogue_conflict']::text[], ARRAY['contrast', 'inner_monologue', 'sensory_detail', 'show_dont_tell']::text[], ARRAY['contrast', 'inner_monologue', 'sensory_detail', 'show_dont_tell']::text[], ARRAY['colloquial', 'humorous', 'short_sentence', 'cinematic']::text[], ARRAY['colloquial', 'humorous', 'short_sentence', 'cinematic']::text[], ARRAY['anger', 'sweetness', 'tension']::text[], ARRAY['anger', 'sweetness', 'tension']::text[], ARRAY['knife', 'light', 'night', 'window']::text[], ARRAY['knife', 'light', 'night', 'window']::text[], 'advance', '{"emotion_tags": ["anger", "sweetness", "tension"], "key_images": ["knife", "light", "night", "window"], "narrative_func": "advance", "scene_type": ["daily_life", "romance", "dialogue_conflict"], "style_summary": "烈日练刀与夜晚卧室冷暖对比，内心吐槽与感官细节交织，把训练苦闷、人物关系暧昧与喜剧感自然融合，节奏张弛有度，结尾以生理性喜欢点破情感张力。", "style_tags": ["colloquial", "humorous", "short_sentence", "cinematic"], "summary": "黎泱被泰诺丢到庄园半月，因嘴硬说不会用刀，被阿义监督在烈日下练刀，反复刺稻草人，阿义公报私仇加练。入夜她穿背心短裙去泰诺卧室卖惨，泰诺在窗边闻到她气味，让她蜷进怀里，对她有生理性喜欢。", "technique": ["contrast", "inner_monologue", "sensory_detail", "show_dont_tell"], "usage_hint": "适合参考日常训练与暧昧场景的冷暖切换、内心独白与感官细节；避免卖惨与勾引边界模糊导致人物动机不清。"}'::jsonb, 'annotated', 'indexed', NULL, 1, TRUE, '2026-10-01T07:15:24.455781+00:00', '2026-10-01T08:01:42.585516+00:00');
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at") OVERRIDING SYSTEM VALUE VALUES (892, 44, 22, 14, 14, '当天晚上，其中一位女郎浑身只穿着一件纱，便进了泰诺的房间。

她怀里温顺地躺着一只猫，正是泰诺那只高傲得六亲不认的布偶猫。

“哈秋！哈秋！哈秋！”黎泱靠在过道上狂打喷嚏。

她揉了揉鼻子，看着泰诺紧锁的房门，嗤笑道:

“呵，真是养不熟的畜生。”', 116, 'time_or_place_boundary', FALSE, 'archived', 1.8, '该场景极短，高度依赖上下文，缺乏完整场景结构。虽然通过猫的转移和黎泱的嘲讽制造了轻微的讽刺与悬念，但信息量低，可迁移的写作手法有限，更适合作为章节钩子而非独立参考范例。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 1.0, "distinctiveness": 2.0, "prose_quality": 2.5, "reference_value": 1.5, "scene_completeness": 1.5, "technique_value": 2.0}, "reference_reason": "该场景极短，高度依赖上下文，缺乏完整场景结构。虽然通过猫的转移和黎泱的嘲讽制造了轻微的讽刺与悬念，但信息量低，可迁移的写作手法有限，更适合作为章节钩子而非独立参考范例。", "reference_score": 1.8, "reference_status": "archived"}'::jsonb, '', '', '', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], '', '{}'::jsonb, 'not_applicable', 'not_applicable', NULL, 1, TRUE, '2026-10-01T07:15:24.455781+00:00', '2026-10-01T08:01:42.585516+00:00');
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at") OVERRIDING SYSTEM VALUE VALUES (910, 44, 40, 27, 27, '第26章 强制爱

“再说吧，我累了。”黎泱推开了泰诺，猛地起身。

两道皮筋划过他的手背，脱离。

这是泰诺没想到的回应。

“确定？”泰诺握着她的手，没有松开。

黎泱慵懒的一声“嗯哼”，尾音上扬。

泰诺:“你就不怕我反悔？”

黎泱耸耸肩:“先生要是这样的人，我也没办法。”

泰诺:“那你之前所干的，不就白干了吗？”

“替先生干活，怎么算白干呢？我只是不要奖励罢了。我多乖啊～”

黎泱还轻佻地勾了勾他下巴。

泰诺一时没有搭话，黎泱便想抽手离开，可手腕却被扼得更紧了。

黎泱挑眉，嘴角挂着一抹晦暗不明的笑:“难不成先生，还想对我强制爱？”

泰诺发出一阵低沉的笑声，但褐灰色的眼眸毫无笑意，良久才说道:

“芍药，你真的很有意思……”

所以呢？莫非真的想强来一炮？

黎泱饶有兴致地等着他后面的话。

“晚安。”泰诺张开了五指，松开了黎泱的手。

动作幅度有点大，显得略微有点夸张。

黎泱斜睨着他。

房间那股腐尸味，挥之不去，令人作呕。

她没有留恋地离开这个臭了的房间。

房间里，只剩泰诺一人。

他来回摩挲着指尖，仿佛上面还残留着她的温度。

没有了她身上的香味，这房间越发显得臭。

“强制……爱？”泰诺低语。

这可以是一个词，也可以拆分成两个词。

但不管怎么组合，都似乎……

与事实不符。

他对她一直都很克制，甚至算得上相敬如宾。

只有为数不多的几次来不及戴上耳机，才会把她

但就算这样，也算绅士，没有什么出格的行为。

可泰诺现在倒是想看看，她哭着求饶的样子，

强制爱听起来，可比书房刺激多了。

泰诺的笑意，点不亮他那双褐灰色的眸。', 622, 'chapter_start', FALSE, 'selected', 3.8, '该场景在对白节奏、动作调度、氛围营造和结尾心理反转上具有可迁移的写作技巧。黎泱与泰诺的对话通过轻佻与克制的交锋制造张力，皮筋脱离、扼腕、松手等动作细节外化权力关系，腐尸味作为感官象征强化关系变质，结尾拆解“强制爱”并转入内心阴暗面，形成有效反转。虽依赖上下文且题材常见，但技巧明确，对学习如何用简短对白和动作控制情绪与悬念有参考价值。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 3.0, "distinctiveness": 3.5, "prose_quality": 4.0, "reference_value": 4.0, "scene_completeness": 4.5, "technique_value": 4.0}, "reference_reason": "该场景在对白节奏、动作调度、氛围营造和结尾心理反转上具有可迁移的写作技巧。黎泱与泰诺的对话通过轻佻与克制的交锋制造张力，皮筋脱离、扼腕、松手等动作细节外化权力关系，腐尸味作为感官象征强化关系变质，结尾拆解“强制爱”并转入内心阴暗面，形成有效反转。虽依赖上下文且题材常见，但技巧明确，对学习如何用简短对白和动作控制情绪与悬念有参考价值。", "reference_score": 3.8, "reference_status": "selected"}'::jsonb, '黎泱拒绝泰诺的奖励并试图离开，泰诺以反悔和白干施压，黎泱轻佻反问是否要强制爱。泰诺最终松手道晚安，黎泱离开。泰诺独自在腐臭房间，摩挲指尖，内心对“强制爱”产生扭曲兴趣，暗示后续可能强取豪夺。', '通过简洁对话展现权力博弈与暧昧张力，动作细节（皮筋、扼腕、摩挲指尖）与感官描写（腐尸味）强化氛围，内心独白揭示角色阴暗面，留白与反转制造悬念。', '适合参考对话中的权力拉扯、感官细节烘托心理、结尾内心独白埋钩子。避免过度解释角色动机，保持克制。', ARRAY['dialogue_conflict', 'emotional', 'romance']::text[], ARRAY['dialogue_conflict', 'emotional', 'romance']::text[], ARRAY['contrast', 'inner_monologue', 'sensory_detail', 'hook']::text[], ARRAY['contrast', 'inner_monologue', 'sensory_detail', 'hook']::text[], ARRAY['dark', 'restrained', 'short_sentence', 'colloquial', 'cinematic']::text[], ARRAY['dark', 'restrained', 'short_sentence', 'colloquial', 'cinematic']::text[], ARRAY['tension', 'anger', 'excitement']::text[], ARRAY['tension', 'anger', 'excitement']::text[], ARRAY['night']::text[], ARRAY['night']::text[], 'advance', '{"emotion_tags": ["tension", "anger", "excitement"], "key_images": ["night"], "narrative_func": "advance", "scene_type": ["dialogue_conflict", "emotional", "romance"], "style_summary": "通过简洁对话展现权力博弈与暧昧张力，动作细节（皮筋、扼腕、摩挲指尖）与感官描写（腐尸味）强化氛围，内心独白揭示角色阴暗面，留白与反转制造悬念。", "style_tags": ["dark", "restrained", "short_sentence", "colloquial", "cinematic"], "summary": "黎泱拒绝泰诺的奖励并试图离开，泰诺以反悔和白干施压，黎泱轻佻反问是否要强制爱。泰诺最终松手道晚安，黎泱离开。泰诺独自在腐臭房间，摩挲指尖，内心对“强制爱”产生扭曲兴趣，暗示后续可能强取豪夺。", "technique": ["contrast", "inner_monologue", "sensory_detail", "hook"], "usage_hint": "适合参考对话中的权力拉扯、感官细节烘托心理、结尾内心独白埋钩子。避免过度解释角色动机，保持克制。"}'::jsonb, 'annotated', 'indexed', NULL, 1, TRUE, '2026-10-01T07:15:24.455781+00:00', '2026-10-01T08:01:42.585516+00:00');
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at") OVERRIDING SYSTEM VALUE VALUES (1049, 44, 179, 121, 121, '“叮”

我尽力了，精彩部分全都删了。都叫你们不要养文，不听不听……', 32, 'rule', FALSE, 'archived', 0.5, '该 Final Scene 是作者在章节末尾的元文本留言，并非叙事场景，没有人物、情节、冲突或描写，不具备可迁移的写作技巧。虽然语气略带幽默，但作为写作参考的价值极低，因此归档。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 5.0, "distinctiveness": 2.0, "prose_quality": 1.0, "reference_value": 0.0, "scene_completeness": 0.0, "technique_value": 0.0}, "reference_reason": "该 Final Scene 是作者在章节末尾的元文本留言，并非叙事场景，没有人物、情节、冲突或描写，不具备可迁移的写作技巧。虽然语气略带幽默，但作为写作参考的价值极低，因此归档。", "reference_score": 0.5, "reference_status": "archived"}'::jsonb, '', '', '', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], '', '{}'::jsonb, 'not_applicable', 'not_applicable', NULL, 1, TRUE, '2026-10-01T07:15:24.455781+00:00', '2026-10-01T08:01:42.585516+00:00');
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at") OVERRIDING SYSTEM VALUE VALUES (875, 44, 5, 3, 3, '第2章 别把人玩死

起码以前，泰诺·帕恩确实瞎过。

黎泱对此，还是比较有把握的。

否则，他胯下的猛兽不会对眼前的活色春香一点反应都没有。

一对男女在床上做活塞运动，渐入高朝。

而泰诺·帕恩就戴着耳机，坐在一旁的沙发上，眼神失焦地落在他们身上。

那时的黎泱，是泰诺身边一个泡茶的女仆，名叫芍药。

化着很重的妆，掩盖了原本张扬的容貌，显得相貌平平。

身份是假的，名字是假的，脸也是假的。

她窝在泰诺的怀里，光明正大地观察他的xx——

在一串串“嗯嗯啊啊”的背景音下，未见异常。

完事后，床上的男人作为泰诺的替身，悄然退下。

而床上的女郎依旧被蒙着眼。

黎泱从泰诺怀里离开，对着床上的女郎说:“你可以摘眼罩了。”

床上的女郎闻言摘下眼罩，按照缅城的礼节匍匐在泰诺的脚下。

泰诺取下耳机，淡然道:“侍候得不错，回去替我谢谢塔丽娜夫人。”

他皮肤很白，衬得眼尾有一点淡红。眉眼生得精致，唇色浅淡，下颌线清浅柔和。

这男人长得太美了，女郎被他那句“侍候得不错”说得心神荡漾。

她扭着腰肢靠近:“塔丽娜夫人说，如果您满意，我可以留在庄园。”

说完，她还抚上泰诺的膝。

男人轻嗤，腿一抖，让女郎扑了个空。

泰诺翘起修长的腿，鞋尖刚好触到女郎的下颚，便一勾，抬起她下巴:

“芍药……她漂亮吗？”

黎泱余光也没给，便说:“她连我的头发丝都比不上。”

女郎一听，瞬间恼火了。她为了这张脸，前前后后一共花了一百万，怎么容得下一个普女诋毁自己？

“你眼瞎呀？！眼瞎就去治！别睁眼说瞎话！我和你谁更好看，瞎的也能看出来！”

还没等黎泱给出反应，泰诺先笑出了声。

他说:“芍药，她骂你是瞎子，你生气吗？”

黎泱了然。

自己生不生气不重要，重要的是，泰诺生气了。

他是金主，得哄着。

金丝雀守则第一条:

【金主生气要么马上哄，要么上马哄。】

黎泱选择了前者。

她用力吸了吸鼻子，带着一点哭腔:“嗯，我很生气，先生您要替我做主。”

女郎更恼火了:“你一个下人，婊里婊气的，看我怎么收拾你！”

女郎上前，对着黎泱就扬起了手。

黎泱一手扼住她手腕，在发力折断的前一秒，看向了自己的金主。

金主无动于衷。

也是，他又看不见。

但总归是能听见的。

于是，黎泱收了手，硬生生地吃下女郎这一巴掌。

“啪”的一声，泰诺挑了挑眉。

但他迟迟没有发话，一只手搭在沙发背上，拇指与食指的指腹来回摩擦。

半晌，才开口:“芍药，过来。”

黎泱捂着半边脸，在他身旁坐下。

泰诺:“生气吗？”

黎泱:“不敢。”

泰诺在怀里掏出了一把匕首，递给她：“她哪里整得比你好看，你就划哪里，直到你消气为止。”

黎泱顿了顿，声音软糯，透着无辜:“脖子能划吗？”

泰诺浅浅勾唇，手摸上黎泱纤细的脖子，温凉的指腹压着跳动的脉搏：

“避开这里，别把人玩死。”', 1087, 'chapter_start', FALSE, 'selected', 4.0, '该场景在有限篇幅内完成了人物关系展示、权力动态、冲突升级和悬念设置。对白节奏紧凑，动作细节（鞋尖抬下巴、拇指摩擦、摸脖子压脉搏）有效传递人物心理与权力关系；通过黎泱的有限视角和内心规则（金丝雀守则）控制信息揭露与情绪张力；结尾以匕首和‘别把人玩死’留白，兼具冲击力与可迁移性。虽语言偏网文风格，但技巧层面值得借鉴。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 3.5, "distinctiveness": 3.5, "prose_quality": 3.5, "reference_value": 4.0, "scene_completeness": 4.5, "technique_value": 4.0}, "reference_reason": "该场景在有限篇幅内完成了人物关系展示、权力动态、冲突升级和悬念设置。对白节奏紧凑，动作细节（鞋尖抬下巴、拇指摩擦、摸脖子压脉搏）有效传递人物心理与权力关系；通过黎泱的有限视角和内心规则（金丝雀守则）控制信息揭露与情绪张力；结尾以匕首和‘别把人玩死’留白，兼具冲击力与可迁移性。虽语言偏网文风格，但技巧层面值得借鉴。", "reference_score": 4.0, "reference_status": "selected"}'::jsonb, '黎泱假扮女仆芍药潜伏在曾失明的泰诺身边。泰诺让替身与女郎欢好，自己戴耳机旁听。事后女郎想留下，泰诺用鞋尖抬其下巴，问芍药谁美。女郎怒骂芍药眼瞎，泰诺试探黎泱是否生气。黎泱为哄金主假装委屈，硬挨女郎一巴掌。泰诺递匕首让黎泱划女郎整容处消气，黎泱问能否划脖子，泰诺摸她脖子脉搏，说避开这里别把人玩死。', '通过极简对话与动作刻画权力博弈，用“金丝雀守则”内心独白点明伪装，以“看不见但听得见”制造张力，暴力与暧昧交织，节奏紧凑，人物关系在试探中推进。', '适合参考病娇金主与卧底女仆的博弈写法，用对话和细节展现控制欲与隐忍。避免过度血腥，注意动机铺垫。', ARRAY['dialogue_conflict', 'emotional', 'romance']::text[], ARRAY['dialogue_conflict', 'emotional', 'romance']::text[], ARRAY['contrast', 'escalation', 'inner_monologue', 'show_dont_tell']::text[], ARRAY['contrast', 'escalation', 'inner_monologue', 'show_dont_tell']::text[], ARRAY['dark', 'restrained', 'short_sentence', 'cinematic']::text[], ARRAY['dark', 'restrained', 'short_sentence', 'cinematic']::text[], ARRAY['tension', 'anger', 'fear']::text[], ARRAY['tension', 'anger', 'fear']::text[], ARRAY['knife', 'blood']::text[], ARRAY['knife', 'blood']::text[], 'conflict', '{"emotion_tags": ["tension", "anger", "fear"], "key_images": ["knife", "blood"], "narrative_func": "conflict", "scene_type": ["dialogue_conflict", "emotional", "romance"], "style_summary": "通过极简对话与动作刻画权力博弈，用“金丝雀守则”内心独白点明伪装，以“看不见但听得见”制造张力，暴力与暧昧交织，节奏紧凑，人物关系在试探中推进。", "style_tags": ["dark", "restrained", "short_sentence", "cinematic"], "summary": "黎泱假扮女仆芍药潜伏在曾失明的泰诺身边。泰诺让替身与女郎欢好，自己戴耳机旁听。事后女郎想留下，泰诺用鞋尖抬其下巴，问芍药谁美。女郎怒骂芍药眼瞎，泰诺试探黎泱是否生气。黎泱为哄金主假装委屈，硬挨女郎一巴掌。泰诺递匕首让黎泱划女郎整容处消气，黎泱问能否划脖子，泰诺摸她脖子脉搏，说避开这里别把人玩死。", "technique": ["contrast", "escalation", "inner_monologue", "show_dont_tell"], "usage_hint": "适合参考病娇金主与卧底女仆的博弈写法，用对话和细节展现控制欲与隐忍。避免过度血腥，注意动机铺垫。"}'::jsonb, 'annotated', 'indexed', NULL, 1, TRUE, '2026-10-01T07:15:24.455781+00:00', '2026-10-01T08:01:42.585516+00:00');
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at") OVERRIDING SYSTEM VALUE VALUES (938, 44, 68, 51, 51, '第50章 莫非你能看得见？

黎泱身体后倾，靠在椅背里，双手交叉环于胸前……

呈一副避让防御的姿态。

她看着泰诺，长长的睫毛眨都不眨一下:

“可惜那半圈啊，芍药还是火候不够，差了两分力……”

当初，泰诺让她用刀刺向自己的时候，也是给出了这样一句类似的评价。

黎泱如今把这句话还给他。

泰诺:“你也不要妄自菲薄，这个事情，能有多少普通人做到？”

他在暗示，黎泱不是普通人。

黎泱笑着耸了耸肩:“先生谬赞，我确实是学艺不精，看来还是要虚心向阿义请教。”

她把她的能力，归功于阿义的教学。

几十公里外的阿义难得休假，在街边吃烤串时，突然打了个喷嚏。

幸好泰诺知道，阿义根本没有这个控制半圈的能耐。

但他没有说破，扯了扯嘴角，垂下的半眸含着眼角那一丁点笑意。

服务员给他们上了餐。

泰诺没再纠结这个话题，铺开餐巾便说:“快吃吧，不是说饿了吗？”

“嗯，好的。”黎泱应下了。

可她不动刀叉，身体继续陷在椅背里，又一次打量着眼前这个男人。

看着他的眸光虚焦在餐桌前侧，又看着他拿着刀叉在牛扒上缓慢挪动——

先用叉子摸索距离，再用餐刀下切。

呵～真是难为他了。

黎泱的指尖捏起了自己的叉子，慢悠悠地垂在半空晃了晃，像在思考……

然后手腕的力一紧，控制着力度把叉子往泰诺面前一甩。

叉子在空中翻转两圈后，叉尖稳稳地扎入泰诺跟前的牛扒。

叉子的齿缝刚好卡住了泰诺的餐刀，发出金属摩擦的声音，迫使泰诺停下。

“怎么了？”泰诺从容地笑道。

“先生不方便，要不芍药帮您切？”她的声音乖巧而甜美。

泰诺也不挣扎，放下手中的刀叉，说了一句:“那就辛苦了。”

黎泱也不含糊，拿过泰诺的牛排，说干就干。

她沿着牛排的纹路，把它切成一块块，然后又重新把食物堆到泰诺面前。

如果泰诺看得见，他就会发现原本聚在一起好好的一整块牛排，此刻被黎泱大卸八块。

最要命的是，她把这八块，都分散在碟子的外围。

东一块西一块，毫不聚拢，反而给看不见的泰诺，上了几个级别的难度。

但泰诺没说什么，好像浑然不知黎泱的小心机，拙慢地用叉子寻找零碎的牛排……

不是，是牛肉粒。

黎泱从他的刀叉中移开了视线，魅惑的狐狸眼盯着他。

过了好一会，她才清了清嗓子，身体微微向前，双臂交叉在桌沿上。

从避让防守的姿态，调整为主动进攻。

“哦对了先生，关于刚刚赵三爷的那个事情，芍药突然想起来，我也有一个小小的疑问，需要先生您帮我解答……”

“说吧。”泰诺用刀叉继续摸索分散在外的牛扒粒。

而黎泱，隔着跳动的烛光，死死地盯着泰诺，声音却很轻柔，还带着点懵懂纯真:

“先生您是怎么知道，我的刀还差半圈就划破赵大三的手腕的？”

这是她第一次把怀疑，摆上了明面。

“莫非你能看得见？”她故作惊讶地捂着嘴。', 1069, 'chapter_start', FALSE, 'selected', 4.2, '该场景通过日常动作（切牛排并分散）外化人物试探与心机，对白潜台词丰富，姿态从防御转为进攻，最后以关键质问制造悬念，具有可迁移的冲突调度与信息揭露技巧。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 3.5, "distinctiveness": 4.0, "prose_quality": 4.0, "reference_value": 4.5, "scene_completeness": 4.5, "technique_value": 4.5}, "reference_reason": "该场景通过日常动作（切牛排并分散）外化人物试探与心机，对白潜台词丰富，姿态从防御转为进攻，最后以关键质问制造悬念，具有可迁移的冲突调度与信息揭露技巧。", "reference_score": 4.2, "reference_status": "selected"}'::jsonb, '黎泱与泰诺在餐厅用餐，她表面乖巧，实则借切牛排试探：故意将牛排切散，观察泰诺摸索。随后她主动进攻，直接问泰诺如何知道她的刀差半圈划破赵大三手腕，并故作惊讶问“莫非你能看得见？”这是她第一次把怀疑摆上明面。', '以日常用餐为壳，用切牛排、甩叉、分散肉粒等动作细节外化试探与心机；对话客气却暗藏锋芒，节奏由缓到紧，结尾提问制造悬念，是“以动作写心理”的范本。', '适合参考用生活化动作承载心理博弈、以细节暗示能力与关系；避免内心独白过多或试探过于直白，保持表面礼貌与内在张力的反差。', ARRAY['dialogue_conflict', 'mystery', 'investigation']::text[], ARRAY['dialogue_conflict', 'mystery', 'investigation']::text[], ARRAY['contrast', 'escalation', 'show_dont_tell', 'hook']::text[], ARRAY['contrast', 'escalation', 'show_dont_tell', 'hook']::text[], ARRAY['cinematic', 'restrained', 'short_sentence', 'colloquial']::text[], ARRAY['cinematic', 'restrained', 'short_sentence', 'colloquial']::text[], ARRAY['tension', 'sweetness', 'excitement']::text[], ARRAY['tension', 'sweetness', 'excitement']::text[], ARRAY['fire', 'knife', 'light']::text[], ARRAY['fire', 'knife', 'light']::text[], 'reveal', '{"emotion_tags": ["tension", "sweetness", "excitement"], "key_images": ["fire", "knife", "light"], "narrative_func": "reveal", "scene_type": ["dialogue_conflict", "mystery", "investigation"], "style_summary": "以日常用餐为壳，用切牛排、甩叉、分散肉粒等动作细节外化试探与心机；对话客气却暗藏锋芒，节奏由缓到紧，结尾提问制造悬念，是“以动作写心理”的范本。", "style_tags": ["cinematic", "restrained", "short_sentence", "colloquial"], "summary": "黎泱与泰诺在餐厅用餐，她表面乖巧，实则借切牛排试探：故意将牛排切散，观察泰诺摸索。随后她主动进攻，直接问泰诺如何知道她的刀差半圈划破赵大三手腕，并故作惊讶问“莫非你能看得见？”这是她第一次把怀疑摆上明面。", "technique": ["contrast", "escalation", "show_dont_tell", "hook"], "usage_hint": "适合参考用生活化动作承载心理博弈、以细节暗示能力与关系；避免内心独白过多或试探过于直白，保持表面礼貌与内在张力的反差。"}'::jsonb, 'annotated', 'indexed', NULL, 1, TRUE, '2026-10-01T07:15:24.455781+00:00', '2026-10-01T08:01:42.585516+00:00');
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at") OVERRIDING SYSTEM VALUE VALUES (1053, 44, 183, 123, 123, '“叮！”

来自作者的碎碎念：

婚礼这一部分，高光在宋家，所以这本就不展开了。新来的宝子有兴趣，可以去看看《禁止侵入》。', 57, 'rule', FALSE, 'archived', 0.0, '该 Final Scene 实为作者在章节末尾的碎碎念/注释，并非叙事场景，不含任何可迁移的写作技巧、对白节奏、冲突、悬念、氛围或情绪控制，对另一位作者没有参考价值。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 5.0, "distinctiveness": 0.0, "prose_quality": 0.0, "reference_value": 0.0, "scene_completeness": 0.0, "technique_value": 0.0}, "reference_reason": "该 Final Scene 实为作者在章节末尾的碎碎念/注释，并非叙事场景，不含任何可迁移的写作技巧、对白节奏、冲突、悬念、氛围或情绪控制，对另一位作者没有参考价值。", "reference_score": 0.0, "reference_status": "archived"}'::jsonb, '', '', '', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], '', '{}'::jsonb, 'not_applicable', 'not_applicable', NULL, 1, TRUE, '2026-10-01T07:15:24.455781+00:00', '2026-10-01T08:01:42.585516+00:00');
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at") OVERRIDING SYSTEM VALUE VALUES (884, 44, 14, 8, 8, '第7章 一啪即散

待黎泱再打开门时，手里的汤碗已经空了。

她走在过道上，随手把空了的碗给了路过的女仆，便径直往茶室走去。

过道里，迎面走来一个男人与她侧身而过。

那人戴着鸭舌帽，帽檐压得很低，看不清脸。身形瘦削，脚步沉稳。

两人擦肩，黎泱回头，看见对方消失在走廊的拐弯处。

茶室里，泰诺一人坐在沙发上，手搭在扶手上，姿势慵懒又疏离。

黎泱走上前，顺手摸了一下客座上的茶杯——

还有些烫手。

看来就是刚刚离开的那个人。

黎泱很少在庄园里，见到有陌生人找泰诺。

他一个病弱的弃子，平日里很少与外界有往来，甚至很少离开庄园。

因为他眼睛看不见，庄园里终日拉着厚厚的窗帘，不怎么透光。所以他的肤色很白，带点病态的白，像抹在墙上的石膏，不带血色。

“芍药？”

泰诺开口，褐灰色的眼睛落在她的方向。

黎泱回过神来，应了一声：“嗯，是我，先生。”

她上前，在他身旁坐下，熟络地往他怀里钻:“先生怎么不喊我过来陪你？”

泰诺:“想你多休息一下，昨晚不累？”

昨晚，泰诺的兴致貌似挺勃勃的，比平日的节制多了几次，快天亮才离开。

泰诺从来不会留在她房间过夜。

这很好，一啪即散，解决完生理需求就分道扬镳。

黎泱不习惯跟别人分半张床。

黎泱:“还好，我不累，反倒是先生您辛苦了。”

毕竟整晚动的又不是她。

泰诺弯起了唇角，把她再往自己的怀里拢了拢。

“哦，对了……”黎泱若无其事地开口:“芍药来的时候，看到一个陌生人，他是谁呀？”

泰诺轻描淡写: “一个帮我干活的人。”

黎泱:“新人？”

泰诺:“旧人。”

黎泱:“以前怎么没见过。”

泰诺笑了笑，没有回答她的问题。

她能看到的，都是他同意的。

黎泱没在意，继续问:“你不是有阿义这个助手了吗？”

泰诺:“阿义帮我干明面上的活，那个人帮我干不见得光的活。”

黎泱:“什么是不见得光的活？”

泰诺:“怎么这么有兴趣？”

泰诺这一问，黎泱意识到自己有点冒进了，赶紧找补:

“芍药也想帮先生您干活。”

“哦？是吗？”泰诺似乎饶有兴致，“你能帮我做什么？”

“芍药的命是先生您救的，先生想让我做什么，我就做什么。”

她像一只乖巧的猫咪，往泰诺的怀里蹭了蹭。

泰诺单手环住了她纤细的腰，另一只手慵懒地伸展，搭在沙发上，指尖虚夹着小小的紫砂茶杯。

“又脏又累，何必呢？”泰诺轻笑。

黎泱正色道:“我不想只当先生的金丝雀、菟丝花，我也想成为先生的左膀右臂，替先生分担。”

泰诺:“我一个被亲妈嫌弃、被家族放弃的瞎子，能有什么分担，都是一些琐事。”

黎泱佯装生气:“那阿义呢？还有刚刚那个陌生人呢？怎么他们就能替先生分担？”

“做什么都行？”泰诺若有所思。

黎泱硬着头皮:“嗯，什么都行。”

指尖的紫砂茶杯在慢悠悠地轻晃，落在黎泱腰间的手不松不紧。

泰诺不烟、不酒，只喜欢喝茶，像个养生的老人渣。

所以他身上偶尔会有股淡淡的茶香，初闻是苦涩的，闻到最后才会有点清幽的甘。

忽而指尖一松，茶杯坠地，发出“砰呲”一声。在寂静的茶室里，显得有点刺耳。

“那就……”，泰诺开口的声音不重，显得很是随意:

“杀人、或者放火，看你喜欢，选一个吧。”', 1219, 'chapter_start', FALSE, 'selected', 4.1, '该场景在有限篇幅内完成了人物关系展示、信息试探、权力博弈与悬念反转。对白节奏紧凑，用亲密动作与日常对话包裹危险信息，结尾以“杀人或放火”的选择制造冲击。细节道具（烫手茶杯、坠地茶杯）有效承担情绪转折。对写作者有可迁移的对话张力与悬念控制技巧，因此值得进入参考库。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 4.0, "distinctiveness": 3.5, "prose_quality": 3.8, "reference_value": 4.2, "scene_completeness": 4.5, "technique_value": 4.2}, "reference_reason": "该场景在有限篇幅内完成了人物关系展示、信息试探、权力博弈与悬念反转。对白节奏紧凑，用亲密动作与日常对话包裹危险信息，结尾以“杀人或放火”的选择制造冲击。细节道具（烫手茶杯、坠地茶杯）有效承担情绪转折。对写作者有可迁移的对话张力与悬念控制技巧，因此值得进入参考库。", "reference_score": 4.1, "reference_status": "selected"}'::jsonb, '黎泱送汤后返回茶室，察觉有陌生人来过，试探询问泰诺。泰诺轻描淡写，黎泱表忠心愿分担，泰诺却让她在杀人或放火中选一个。对话在亲昵与试探中推进，结尾突转，悬念陡生。', '本段以日常茶室对话为壳，通过茶杯烫手、茶香、茶杯坠地等细节营造暗流涌动的氛围。人物关系在亲昵与试探中展开，结尾一句“杀人或放火”瞬间反转，将甜腻对话推向危险边缘，是“温柔刀”式写法的范本。', '适合参考用日常互动铺垫冲突、以动作细节暗示权力关系；避免对话过于直白或信息堆砌，需保持克制与留白。', ARRAY['dialogue_conflict', 'mystery', 'romance']::text[], ARRAY['dialogue_conflict', 'mystery', 'romance']::text[], ARRAY['contrast', 'foreshadow', 'sensory_detail', 'twist']::text[], ARRAY['contrast', 'foreshadow', 'sensory_detail', 'twist']::text[], ARRAY['dark', 'restrained', 'short_sentence', 'cinematic']::text[], ARRAY['dark', 'restrained', 'short_sentence', 'cinematic']::text[], ARRAY['tension', 'fear', 'sweetness']::text[], ARRAY['tension', 'fear', 'sweetness']::text[], ARRAY['fire', 'knife', 'light', 'night']::text[], ARRAY['fire', 'knife', 'light', 'night']::text[], 'cliffhanger', '{"emotion_tags": ["tension", "fear", "sweetness"], "key_images": ["fire", "knife", "light", "night"], "narrative_func": "cliffhanger", "scene_type": ["dialogue_conflict", "mystery", "romance"], "style_summary": "本段以日常茶室对话为壳，通过茶杯烫手、茶香、茶杯坠地等细节营造暗流涌动的氛围。人物关系在亲昵与试探中展开，结尾一句“杀人或放火”瞬间反转，将甜腻对话推向危险边缘，是“温柔刀”式写法的范本。", "style_tags": ["dark", "restrained", "short_sentence", "cinematic"], "summary": "黎泱送汤后返回茶室，察觉有陌生人来过，试探询问泰诺。泰诺轻描淡写，黎泱表忠心愿分担，泰诺却让她在杀人或放火中选一个。对话在亲昵与试探中推进，结尾突转，悬念陡生。", "technique": ["contrast", "foreshadow", "sensory_detail", "twist"], "usage_hint": "适合参考用日常互动铺垫冲突、以动作细节暗示权力关系；避免对话过于直白或信息堆砌，需保持克制与留白。"}'::jsonb, 'annotated', 'indexed', NULL, 1, TRUE, '2026-10-01T07:15:24.455781+00:00', '2026-10-01T08:01:42.585516+00:00');
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at") OVERRIDING SYSTEM VALUE VALUES (1055, 44, 185, 124, 124, '又来一个“叮”！

写到这里，这本书准备结束了。熟悉我的包子都知道，我不爱水文，不喜欢在一起，又各种误会各种分开。

所以，大家还有什么想看的，可以留个言，不保证能满足，只能说尽量。', 87, 'rule', FALSE, 'archived', 0.5, '该场景为作者在章节末尾的留言，属于元叙事而非小说叙事内容，缺乏人物、情节、对话、描写等可迁移的写作技巧，对另一位作者的写作参考价值极低。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 1.0, "distinctiveness": 0.5, "prose_quality": 1.0, "reference_value": 0.0, "scene_completeness": 0.0, "technique_value": 0.5}, "reference_reason": "该场景为作者在章节末尾的留言，属于元叙事而非小说叙事内容，缺乏人物、情节、对话、描写等可迁移的写作技巧，对另一位作者的写作参考价值极低。", "reference_score": 0.5, "reference_status": "archived"}'::jsonb, '', '', '', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], '', '{}'::jsonb, 'not_applicable', 'not_applicable', NULL, 1, TRUE, '2026-10-01T07:15:24.455781+00:00', '2026-10-01T08:01:42.585516+00:00');
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at") OVERRIDING SYSTEM VALUE VALUES (1004, 44, 134, 95, 95, '第94章 我允许你离开了吗？

塔丽娜前脚刚走，一个满身酒气的男人又破门而入，像是早在门口虎视眈眈多时。

“你进来干什么？！”黎泱呵斥来人。

她认出闯进来的人，是二房那出了名纨绔的儿子，泰雄。

帕恩家族如今的当家人赫巴农·帕恩年纪渐大，表面上已经不理家族业务，所以帕恩家族内斗厉害。

他总共有五个老婆，20个儿女，呼声最高的是大房塔丽娜夫人，其次是二夫人萨维琶。

这个男人，就是二房的人。

男人堵在门口，看样子醉得不轻，正不怀好意地打量着黎泱。

“你这脸长得很一般，身材倒是不错。”

他关上身后的门，并“咔哒”一声上了锁。

黎泱起了一身鸡皮。

“泰雄少爷，你要耍酒疯就滚远一点，这里不是红灯区。”

但泰雄一脸淫笑，变本加厉，往前几步，把黎泱往床那边逼去。

“那个废人一开始还非你不娶，但就你这张脸啊，看来是你的床上功夫了得，让那条废柴欲仙欲死啊。”

黎泱眸色锋利:“我劝你把嘴巴放干净一点。”

泰雄嘿嘿笑了几声:“那废人都快结婚了，他又病弱，怎么喂饱你？现在你先让我试试，确实够骚的话，我让你跟我。”

黎泱一副吃了屎的表情:“你说什么？”

“我让你这sao货跟了我。”

说完，他就扑上来，准备扯黎泱衣服。

黎泱没有后退，抬腿就是一脚，快准狠。

“啊！”

泰雄惨叫一声，没想到一个暖床的女仆，能这么刚。

他一手捂着下体，一脸痛苦的样子，一手指着黎泱的鼻尖，恶狠狠说：“我再给你一次机会，你最好想清楚……”

黎泱抬腿又是一脚。

这回，泰雄痛得彻底倒地。

“谢谢你给的机会。”

黎泱说完便潇洒离开，像是什么都没发生过。

可走出房门后，黎泱突然不知道自己能去哪。

整个庄园这么大，只有泰诺的房间属于她，但如今，里面有个挣扎着的人渣。

就在这时，她收到宋迦木的电话。

“上次我让你偷的那个U盘，上面的地址我已经破译到了，要一起去看看吗？”宋迦木在电话那头说。

黎泱环视了一眼四周。

这里是帕恩庄园，不是泰诺的地盘，没有那么多他的眼线，她要进出这里，反而比以前简单得多。

况且，泰诺又不在，她可以去去就回。

“行，马上。”黎泱对着电话说道。

可她万万没想到，自己被宋迦木忽悠去了一个荒郊野岭的地方。

那日，她趁乱帮宋迦木偷的，是帕恩集团下面某个小公司的账本。

他们顺藤摸瓜，发现这深山里藏了一个有军火把守的仓库。

如今，宋迦木已经把自己的假妹妹宋衾萝，也就是那个要跟泰诺联姻的宋家大小姐押到了缅城。

听说，也是个不好伺候的主，折腾得很。

所以宋迦木必须赶回去盯着她。

黎泱由于某个难以启齿的原因，被迫留在这个荒山野岭里，监视着仓库，摸清楚它的轮岗排班。

待了整整三天。

等她一身泥巴再回到帕恩庄园时，推开泰诺房间的门，看见泰诺坐在里面，脸黑得像压了一整片乌云。

他偏过头，声音带着一种被压了很久才放出来的重量：

“我允许你离开了吗？”

“砰”

他捏碎了他手里那口薄瓷茶杯。

瓷片扎入他指尖，鲜血涌了出来。', 1146, 'chapter_start', FALSE, 'archived', 2.7, '该场景虽具备完整的冲突、动作与悬念结尾，但整体属于常见网文桥段（纨绔骚扰、女主反击、霸道男主质问），语言直白且依赖前文人物关系与背景，可迁移的写作技巧较为常规，缺乏独特且高价值的参考点，更适合作为剧情推进归档。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 2.5, "distinctiveness": 2.0, "prose_quality": 2.5, "reference_value": 2.5, "scene_completeness": 3.0, "technique_value": 2.5}, "reference_reason": "该场景虽具备完整的冲突、动作与悬念结尾，但整体属于常见网文桥段（纨绔骚扰、女主反击、霸道男主质问），语言直白且依赖前文人物关系与背景，可迁移的写作技巧较为常规，缺乏独特且高价值的参考点，更适合作为剧情推进归档。", "reference_score": 2.7, "reference_status": "archived"}'::jsonb, '', '', '', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], '', '{}'::jsonb, 'not_applicable', 'not_applicable', NULL, 1, TRUE, '2026-10-01T07:15:24.455781+00:00', '2026-10-01T08:01:42.585516+00:00');
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at") OVERRIDING SYSTEM VALUE VALUES (958, 44, 88, 67, 67, '第66章 你敢爱吗？

黎泱的心咯噔了一下。

这人是怎么回事？不仅没断片，怎么还这么记仇！？

她别开脸，挣脱了他桎梏自己下巴的手:“接吻这种事嘛，讲的是天时地利人和，是强求不来的。”

“强求？”泰诺轻笑，拇指与食指的指尖来回摩挲，他还是喜欢捏着她下巴的感觉。

就像能掌控她一样。

“你刚刚不是才说喜欢我？全身心地喜欢我？现在怎么就变强求了？”泰诺勾着唇，但没什么笑意。

黎泱暗骂自己，怪自己撒谎不打草稿！

但她也骂泰诺，明知道双方都是逢场作戏，大家笑笑就算了，干嘛较真？！

黎泱不知道该怎么圆谎。

实在不行，要不说他口臭吧？

哎不行，他是金主。

那就说……自己口臭吧？？

唔……

也不是不行。

黎泱:“先生，其实我……”

泰诺打断她。

这一次，他并不打算随便让黎泱蒙混过关，他要直戳她的要害，直捣她的黄龙。

“芍药，你都把身体给了我，接个吻而已，你在害怕什么？”

黎泱滞了一瞬。

害怕？

害怕什么？

她是因为害怕吗？

为什么？

性，是生理需求。哺乳类动物繁衍生息的天性。

所以她和他做，很正常哒，他就是自己的一个成人玩具而已。

不是他泰诺·帕恩，她也可以找别人。

那，接吻呢？

黎泱不想往深入去想，只能下意识地反驳:“我没有怕。”

泰诺:“不怕吗？”

黎泱:“不怕。”

“是吗？”泰诺眉梢抬起，绯唇轻启，“那你现在吻我。”

黎泱张了张嘴，僵住。

她当然不可能吻上去，激将法对她没有用。

但事已至此，她也不知道该如何收场。

沉默被拉得很长，最后换来黎泱的一声叹息:“好吧先生，事到如今，我也不想瞒你了。”

泰诺:“说。”

黎泱重重地吸了一口气，手抬起，捂上了她的小心肝……

“其实……其实……我是有未婚夫的人。”

泰诺似乎并不惊讶，平静地问:“哪来的？”

黎泱:“我爸妈在乡下给我找的一门亲事。”

泰诺:“什么时候？”

“前段时间吧。”黎泱尽量说得模棱两可。

泰诺:“所以呢？这两者有什么关系？”

黎泱张口就来:“我要把初吻，留给我未婚夫。”

泰诺:“当真？”

黎泱:“嗯呐。”

泰诺轻嗤一声:“那还真有意思。”

褐灰色的眼眸弯起，眼角噙着讥讽的笑。

泰诺:“你要把初吻留给未婚夫，可你却把初夜给了别的男人。”

黎泱语滞。

她也觉得，这个借口是自己脑抽风了。

泰诺的手抵住黎泱的后腰，把她整个人压向自己。

他的气息强势包裹着她。

泰诺:“既然要守身如玉，那为什么一次又一次地和我上床？

“既然要和我上床，为什么不能毫无保留地把自己给我？

“每一次都差一步，是什么意思？芍药，你到底想怎样？”

“咳咳……”黎泱被他的话呛到。

自己在他的话里，怎么像个玩弄感情的渣女？

不就是不接吻而已吗？

她错哪了？！她十恶不赦了吗？！

呸！她没错！

“对不起先生！是我错了，我以后改正！”黎泱咬咬牙，说得并不情愿。

泰诺:“什么意思？以后不上了？”

黎泱硬着脖子:“嗯，不上了。”

泰诺:“我同意了吗？”

黎泱的音调上扬:“这事还要经先生批准？”

泰诺:“是。”

黎泱恼了:“呵～这么说来，难道先生您还想强制爱？”

泰诺:“我要是强制，你敢爱吗？”', 1194, 'chapter_start', FALSE, 'selected', 3.8, '该场景以对白驱动，围绕“接吻”与“初吻/初夜”的逻辑矛盾展开权力博弈，冲突层层升级，内心独白与对白交替，结尾以“我要是强制，你敢爱吗？”制造悬念。虽语言偏网文口语，但节奏、情绪控制、信息揭露和钩子设计具有可迁移性，适合作为对白冲突与情绪推拉的参考样本。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 3.5, "distinctiveness": 3.0, "prose_quality": 3.0, "reference_value": 3.8, "scene_completeness": 4.0, "technique_value": 3.8}, "reference_reason": "该场景以对白驱动，围绕“接吻”与“初吻/初夜”的逻辑矛盾展开权力博弈，冲突层层升级，内心独白与对白交替，结尾以“我要是强制，你敢爱吗？”制造悬念。虽语言偏网文口语，但节奏、情绪控制、信息揭露和钩子设计具有可迁移性，适合作为对白冲突与情绪推拉的参考样本。", "reference_score": 3.8, "reference_status": "selected"}'::jsonb, '黎泱被泰诺逼问为何抗拒接吻，情急下谎称有未婚夫、要把初吻留给他。泰诺冷静戳穿她已把初夜给了别人，步步紧逼质问其矛盾。黎泱恼羞成怒宣布不再上床，泰诺反问“我要是强制，你敢爱吗？”对话在张力中收束。', '对话紧凑，心理活动与动作细节穿插，通过谎言与反诘层层推进，人物性格在交锋中凸显，节奏张弛有度，是情感博弈的范本。', '适合参考对话冲突中的心理博弈与谎言戳穿技巧；避免内心吐槽过多导致节奏拖沓。', ARRAY['dialogue_conflict', 'emotional', 'romance']::text[], ARRAY['dialogue_conflict', 'emotional', 'romance']::text[], ARRAY['inner_monologue', 'escalation', 'show_dont_tell', 'twist']::text[], ARRAY['inner_monologue', 'escalation', 'show_dont_tell', 'twist']::text[], ARRAY['colloquial', 'fast_paced', 'humorous', 'short_sentence']::text[], ARRAY['colloquial', 'fast_paced', 'humorous', 'short_sentence']::text[], ARRAY['tension', 'anger', 'fear']::text[], ARRAY['tension', 'anger', 'fear']::text[], ARRAY['fire', 'knife']::text[], ARRAY['fire', 'knife']::text[], 'conflict', '{"emotion_tags": ["tension", "anger", "fear"], "key_images": ["fire", "knife"], "narrative_func": "conflict", "scene_type": ["dialogue_conflict", "emotional", "romance"], "style_summary": "对话紧凑，心理活动与动作细节穿插，通过谎言与反诘层层推进，人物性格在交锋中凸显，节奏张弛有度，是情感博弈的范本。", "style_tags": ["colloquial", "fast_paced", "humorous", "short_sentence"], "summary": "黎泱被泰诺逼问为何抗拒接吻，情急下谎称有未婚夫、要把初吻留给他。泰诺冷静戳穿她已把初夜给了别人，步步紧逼质问其矛盾。黎泱恼羞成怒宣布不再上床，泰诺反问“我要是强制，你敢爱吗？”对话在张力中收束。", "technique": ["inner_monologue", "escalation", "show_dont_tell", "twist"], "usage_hint": "适合参考对话冲突中的心理博弈与谎言戳穿技巧；避免内心吐槽过多导致节奏拖沓。"}'::jsonb, 'annotated', 'indexed', NULL, 1, TRUE, '2026-10-01T07:15:24.455781+00:00', '2026-10-01T08:01:42.585516+00:00');
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at") OVERRIDING SYSTEM VALUE VALUES (1011, 44, 141, 97, 97, '“叮”

读到这里的读者宝宝们，球球别跑到前面评论区剧透啊

我辛苦设计的伏笔，你们都跑去剧透的话，对我是一种伤害哇', 54, 'rule', FALSE, 'archived', 0.0, '该文本是作者在章节末尾对读者的直接喊话，属于元文本/作者注，而非小说叙事场景。它不包含人物、情节、环境等小说要素，不具备可迁移的写作技巧或叙事参考价值。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 5.0, "distinctiveness": 1.0, "prose_quality": 1.0, "reference_value": 0.0, "scene_completeness": 0.0, "technique_value": 0.0}, "reference_reason": "该文本是作者在章节末尾对读者的直接喊话，属于元文本/作者注，而非小说叙事场景。它不包含人物、情节、环境等小说要素，不具备可迁移的写作技巧或叙事参考价值。", "reference_score": 0.0, "reference_status": "archived"}'::jsonb, '', '', '', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], '', '{}'::jsonb, 'not_applicable', 'not_applicable', NULL, 1, TRUE, '2026-10-01T07:15:24.455781+00:00', '2026-10-01T08:01:42.585516+00:00');
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at") OVERRIDING SYSTEM VALUE VALUES (909, 44, 39, 26, 26, '第25章 杀人这活太累了

阿义强忍着胃部翻滚的不适，拉上了装尸袋的拉链，对泰诺说道:

“是尸首，容貌被水浸泡过，看得不清……”

泰诺打断他，慢悠悠地说:“连你都看得不清，谁还能看得清？”

就是。

再怎么说，尸袋里躺着的，也是阿义亲自找回来的女人。

阿义只好硬着头皮，拉开拉链再深深地看了几眼。

“是是是的，看这基本的轮廓，没错了。”阿义连忙拉上袋子，胃里翻腾着干呕。

泰诺摆了摆手，示意他将尸身拖走。

黎泱站在几步之外，扇了扇自己鼻前的气息。

阿义果然比泰诺好忽悠多了。

这里是缅城，东南亚。

每天莫名死亡、失踪的人很多。

宋迦木负责去乱葬岗拣货，她黎泱负责易容。

最后，用一条易了容的假尸，把阿义成功打发。

阿义离开后，黎泱把窗户再打开了些，散散房间里的气味。

“芍药，过来。”泰诺朝黎泱的方向抬手，温声道。

黎泱刚握上他的手，就被拉入他结实的胸膛。

男人的手抚上她的腰侧，手很大，几乎环住了她半个腰身，温热的掌心隔着衣料贴上来。

他垂首，气息扫过她纤细的脖子:“好玩吗？”

黎泱佯装没听到:“什么？”

泰诺勾了勾唇角:“杀人。”

黎泱食指抵着泰诺的胸膛，把他稍稍推开，娇嗔一句:

“先生说什么呢，人可不是我杀的。”

泰诺:“哦？”

黎泱:“是您母亲派人杀的，跟我一点关系都没有。”

泰诺脸上的笑意更深，任她嚣张地把话说完。

“杀人这活太累了，芍药干不来。所以芍药也跟先生一样，手不沾血。”

说罢，她的手抚上那张帅得让人神魂颠倒的脸，拇指轻轻摩挲。

泰诺握住那双手，收紧了掌心，像是把一只扑扇翅膀的蛾，扣进了笼子里。

“我就喜欢你的聪明，”他笑了，笑意从唇角漫到眼底，“每一次都能给我带来惊喜。”

黎泱软在他怀里，鼻尖蹭过他的下颌线，呼吸拂过他的喉结：“先生只喜欢我的聪明？”

泰诺没回答，而是低下头，唇几乎贴着她的耳廓，气息温热，一字一顿：

“选吧，想去哪里做？”

原本搭在她腰侧的手，此刻已经不满足于隔着布料的摩挲，悄然滑入衣摆的边缘，贴上她腰间的皮肤。

带着薄茧的粗粝，从腰侧慢慢往前游走，一寸一寸抚过她平滑的小腹。

她的小腹在他掌下绷紧了。

“太紧了，放松。”

泰诺故意把气息砸到她的耳廓上，掌心在她腹部打圈，继而往下探……

黎泱按住他那双已潜到裙子皮筋下的手。

“先生这是想好，要兑现承诺了？”

当初他说，帮他解决这两个女人，就会给黎泱奖励。

奖励就是，去哪里做，黎泱说了算。当然包括她心心念念的书房。

空气变得又黏又稠。

灯光昏黄，两个人的影子叠在一起，投在身后的墙上，分不清谁是谁。

泰诺无视黎泱按住的手，缓缓地继续前进，又过了一道细细的皮筋。

两道皮筋勒在他手背上。

他没有给个明确答复，只是帮黎泱铺好了台阶:“想去书房吗？”

这段时间由于两人的博弈，好久没有睡过了。

不是睡觉的睡。

距离上一次泰诺把她摁在窗边，已经过去了将近一个月。

他已经快一个月没碰她了。

泰诺不否认自己对她的想念，但也仅仅是生理性的。

换句话说，他想念的，是她的肉体。

不能怪他心冷，这个女人又何尝对自己动过真心？

她也就只有在床上的反应，是真实的。

每一次的潮红，每一声的吟诵……

哪怕她说“慢一点”“不行了”也是真的。

更别提她会说“别磨了”“给我”。

那一刻，他爱死了她不带修饰的直白。

所以这次，她既然已经“听话”地投诚了，那个早就装有窃听器的书房，又有什么所谓？

如她所说，枕着圣人言，行苟且之事，确实够刺激。

那两道皮筋，缓缓碾过他的手背，来到他的手腕处。', 1368, 'chapter_start', FALSE, 'selected', 4.2, '该场景在有限篇幅内完成多重叙事功能：打发阿义、揭示假尸骗局、展现男女主权力与情欲博弈、埋下书房窃听器悬念。对白简洁且充满潜台词，身体动作与心理描写交织，用‘皮筋’等细节制造性张力，信息揭露自然。虽依赖部分前文设定，但场景内自洽，可独立理解。对写作者在冲突调度、暧昧张力、信息埋设与人物关系刻画上有可迁移的参考价值。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 3.8, "distinctiveness": 4.0, "prose_quality": 3.8, "reference_value": 4.5, "scene_completeness": 4.5, "technique_value": 4.3}, "reference_reason": "该场景在有限篇幅内完成多重叙事功能：打发阿义、揭示假尸骗局、展现男女主权力与情欲博弈、埋下书房窃听器悬念。对白简洁且充满潜台词，身体动作与心理描写交织，用‘皮筋’等细节制造性张力，信息揭露自然。虽依赖部分前文设定，但场景内自洽，可独立理解。对写作者在冲突调度、暧昧张力、信息埋设与人物关系刻画上有可迁移的参考价值。", "reference_score": 4.2, "reference_status": "selected"}'::jsonb, '阿义被泰诺和黎泱用易容假尸骗过，误认女尸为宋迦木。阿义离开后，泰诺与黎泱调情，黎泱以聪明和娇嗔撇清杀人嫌疑，泰诺则欣赏她的聪明，并借兑现承诺之名，将手探入她衣下，暗示去装有窃听器的书房发生关系。', '本段以细腻的感官描写和权力博弈推进暧昧张力，通过肢体接触、气息、皮筋等细节展现控制与服从，对话简短却暗藏机锋，是情欲与算计交织的范本。', '适合参考如何用身体语言和微动作写权力调情，避免直白情色描写，注意保持角色智商在线，让暧昧服务于人物关系推进。', ARRAY['romance', 'dialogue_conflict', 'emotional']::text[], ARRAY['romance', 'dialogue_conflict', 'emotional']::text[], ARRAY['sensory_detail', 'show_dont_tell', 'escalation', 'contrast']::text[], ARRAY['sensory_detail', 'show_dont_tell', 'escalation', 'contrast']::text[], ARRAY['cinematic', 'dark', 'restrained', 'short_sentence']::text[], ARRAY['cinematic', 'dark', 'restrained', 'short_sentence']::text[], ARRAY['tension', 'sweetness', 'excitement']::text[], ARRAY['tension', 'sweetness', 'excitement']::text[], ARRAY['light', 'window', 'night']::text[], ARRAY['light', 'window', 'night']::text[], 'advance', '{"emotion_tags": ["tension", "sweetness", "excitement"], "key_images": ["light", "window", "night"], "narrative_func": "advance", "scene_type": ["romance", "dialogue_conflict", "emotional"], "style_summary": "本段以细腻的感官描写和权力博弈推进暧昧张力，通过肢体接触、气息、皮筋等细节展现控制与服从，对话简短却暗藏机锋，是情欲与算计交织的范本。", "style_tags": ["cinematic", "dark", "restrained", "short_sentence"], "summary": "阿义被泰诺和黎泱用易容假尸骗过，误认女尸为宋迦木。阿义离开后，泰诺与黎泱调情，黎泱以聪明和娇嗔撇清杀人嫌疑，泰诺则欣赏她的聪明，并借兑现承诺之名，将手探入她衣下，暗示去装有窃听器的书房发生关系。", "technique": ["sensory_detail", "show_dont_tell", "escalation", "contrast"], "usage_hint": "适合参考如何用身体语言和微动作写权力调情，避免直白情色描写，注意保持角色智商在线，让暧昧服务于人物关系推进。"}'::jsonb, 'annotated', 'indexed', NULL, 1, TRUE, '2026-10-01T07:15:24.455781+00:00', '2026-10-01T08:01:42.585516+00:00');
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at") OVERRIDING SYSTEM VALUE VALUES (1013, 44, 143, 98, 98, '黎泱回到泰诺的庄园，发现阿兰不见了。

她问了几位跟阿兰比较相熟的姐妹，她们都只是说，阿兰是突然离开的。

没有预兆，没有告别，就像是被人从这座庄园里无声地抹去了一样。

黎泱站在走廊里，感觉到自己后背正在一寸一寸地发凉。

她想起同样失联的胡建明。

阿兰消失前，答应她会帮她查胡建明的下落。

一个消失可以说是巧合，两个都消失了，那就不可能是巧合。

她开始怀疑，他们两个是否已经遭遇了不测。

而阿兰的身份，是泰诺告诉她的。

泰诺知道她是卧底。

那么，如果阿兰真的出了什么事，最有能力、也最有可能对她动手的人，就是泰诺。

她站在那里，感觉到走廊尽头的光线正在慢慢变暗。

在这座庄园里，每个人都在演一场戏，而她自己的剧本，也快要翻页了。

这时候，电话响起。

刚接起就传来宋迦木低沉而轻佻的声音。

“要出海玩吗姐姐？我们可以提供服务哦。”

黎泱：“入了什么新的货色？”

宋迦木：“我猜，我们想要的东西都在那条船上能找到。”

黎泱：“哪条船？”

宋迦木：“泰诺帕恩的船。”

黎泱：“好，我会想办法上船。”

宋迦木沉沉地笑了笑：“我也打算带我家妹妹上船去见见世面。千金小姐嘛，没接触过什么人间疾苦，怕把她养娇气了。”

黎泱皱了皱眉:“你又打人家什么主意？”

宋迦木:“我要试试她，她藏有太多秘密了。”

“你爱咋咋的。”黎泱挂了销售经理的电话。

晚上，黎泱在睡觉时，有人摸黑开了门，爬上了床。

床垫凹陷，熟悉的气息从身后包裹了她。

“先生。”

泰诺：“我吵醒你了吗？”

黎泱：“没有，我还没睡着，你怎么来了？”

安静了几秒，他的声音才从身后传来：“我想你了。”

下巴轻轻搁在她发顶，他的声音带着一种被夜色浸透过的低哑：“但你经常躲在这里，那只能我来找你了。”

黎泱转身，回抱着他，把脸埋在他胸前。

多么相亲相爱的一个动作。

黎泱有时候真的会信，他们会有天长地久的时候。

可现实往往很骨感。

“先生，阿兰去哪里了？我这次回来，一直没看见她。”

泰诺顿了顿：“她请假回老家了。”

“回老家？”黎泱重复了一遍。

泰诺：“嗯。”

黎泱：“先生当初跟我说，她是卧底，先生怎么不趁机解决她，还把她留在身边？”

泰诺不急不慢地说:“你除掉一个，敌人便会再派一个，你不能保证把他们都找出来。所以我说过，要把别人的棋子，控制在自己手里。敌在明，我在暗。”

黎泱：“也就是说，你哪怕知道她是卧底，你也不会动她？”

泰诺：“不会。”

黎泱靠在他怀里，没有追问。

像一枚暂时停在原地的棋子，还没有决定下一步该怎么移动。

“先生……你最近还是很忙吗？”

泰诺:“怎么了？”

黎泱:“我想出海散散心。”

泰诺挑了挑眉：“出海？”

黎泱抬眼看他：“就去你上次带我去的那艘船，怎么样？”

泰诺的眸光落在她身后，没有聚焦，但余光却能捕捉到那双狐狸眼里，漆黑的眸。

“好。”

黎泱：“那这一次，我可以去16层的会所看看了吗？”

泰诺：“为什么你对那个会所感兴趣？”

黎泱:“因为先生不让我去啊。人就是这样，越被拒绝，越想得到。”

“确实。”搭在黎泱腰上的手，加了几分力，把人再往自己怀里带了带。

“既然你想看，我就带你去。”他的气息拂过她的耳垂。

黎泱眨了眨眼:“今晚先生要留下吗？”

泰诺:“你说呢？都。”

黎泱说:“你还是回去吧，我来例假了。”

泰诺愣了愣，然后起身下了床。

黎泱以为他会离开，所以她很快便睡着了。

在她入睡后，泰诺才从浴室里处理完，再回到她的房间。

房间漆黑一片，这个女人连一盏灯都不留给他。

他蹑手蹑脚地上了床，把熟睡的她，重新拢到自己怀里。

感受到她甜得发腻的气息，一吸一呼，泰诺慢慢合上了眼。', 1416, 'rule', FALSE, 'archived', 3.0, '场景完整，对白有潜台词和悬念推进，心理描写与动作细节尚可，但整体属于常规剧情推进，依赖较多前文设定（卧底、庄园权力关系、人物身份），技巧和语言未达到特别突出的可迁移参考价值，因此归档。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 2.5, "distinctiveness": 2.5, "prose_quality": 3.0, "reference_value": 3.0, "scene_completeness": 4.0, "technique_value": 3.0}, "reference_reason": "场景完整，对白有潜台词和悬念推进，心理描写与动作细节尚可，但整体属于常规剧情推进，依赖较多前文设定（卧底、庄园权力关系、人物身份），技巧和语言未达到特别突出的可迁移参考价值，因此归档。", "reference_score": 3.0, "reference_status": "archived"}'::jsonb, '', '', '', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], '', '{}'::jsonb, 'not_applicable', 'not_applicable', NULL, 1, TRUE, '2026-10-01T07:15:24.455781+00:00', '2026-10-01T08:01:42.585516+00:00');
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at") OVERRIDING SYSTEM VALUE VALUES (889, 44, 19, 13, 13, '第12章 金丝雀vs金毛鸭

黎泱内心的两个小人在打架。

眼看善良正直的小人，准备打败升职加薪的小人……

胸前的纽扣突然被解开。

嗯？

黎泱低头，又抬头看向始作俑者。

“你湿了。”

泰诺一贯慵懒的音调像蚂蚁爬过黎泱的耳廓。

继而第二、第三、第四颗纽扣被解开。

“把衣服脱了。”

泰诺将她半湿的衣服褪到臂弯处，露出了白色纯欲的蕾丝内衣。

他看不见，所以指尖摸索着，划过她一寸又一寸的肌肤。

黎泱没动，任由眼前的男人脱下自己的衣服。

狗男人。

借口还挺多，想吃就直说。

忽然，一件花色开衫披在了黎泱身上，裹住她外露的肌肤。

嗯？

黎泱又一次低头，自己身上披着的，是泰诺的衬衫。

她正狐疑地看向他，就被他肌肉线条流畅的双臂圈入怀里。

泰诺一手从衣摆里探入，掌心贴在她温凉光滑的后腰，护着。

另一只手，拿着黎泱那件衣服并未浸湿的部分，擦拭她被头发打湿的后背。

泰诺:“下次，记得把头发吹干再来找我。”

湿了的肌肤带点温凉，显得抵在后腰的掌心很烫。

一阵热浪窜到了黎泱的脊梁骨，她愣愣地开口问:“为什么？”

泰诺的语气带着几分笑意，擦拭的手没停下:“小时候没人教你，这样容易生病吗？”

哦，教过……

她妈妈好像也是这样，边替她擦着身体，边唠叨她。

不过后来，她妈跟别的男人跑了以后，就没人管她了。

毕竟，也不可能让她爸来干这种事。

被圈着的黎泱没有吱声，本就跨坐在泰诺身上的她，往深挪了挪。

直到她的大腿被他劲瘦的腰卡住，她索性就靠在了泰诺的怀里。

白色蕾丝贴着他的黑色背心。

该软的软，该硬的硬。

黎泱喜欢泰诺身上的滚烫，看着就是气血很足的样子。

特别是高强度运动过后……

“先生～”

“嗯？”

“想要。”

后背的手顿住了，片刻才传来男人的声音:“你把那两个女人解决了，下一次……”

“下一次是下一次的事，”黎泱打断他，“这次是现在的事。”

卧室里安静了，只剩彼此的呼吸。

她是他的金丝雀又如何？

他也可以是她哄骗来的金毛鸭。

男欢女爱，就没有谁比谁更吃亏的道理。

享受的那个就是赢家。

后背的卡扣被打开，炽热的掌心替代粗糙的布料，覆在她微微湿凉的背上。

他顺了她的意，吻落在她的颈窝。

她稍稍耸起了肩，花色开衫从她肩头滑落。

他重新戴上另一边的耳机，并调高了音量。

夏夜有点风，吹得黎泱有点冷。

黎泱掩上了双开门的木窗。

，，，，，

嗐，白关了。

动能转化成热能。

夜风吹着她鬓边的头发，发丝撩到泰诺的脸上，有点痒，但他腾不出手，便索性把头埋在她秀发里。

甜得发腻的气息，让泰诺想起那肆意舔弄的雪糕。

结实的胸膛撞击着耸起的蝴蝶骨，说不清谁比谁更痛。

耳机里循环播放着清心咒，身体却干着凡尘间的俗事。

很割裂。

可他顶着一副这么完美的皮囊，又显得很和谐。

她趴在窗上，吹着清风；

他听着清心咒。

好一对附庸风雅的男女。', 1092, 'chapter_start', FALSE, 'selected', 3.8, '该场景在亲密场景写作上展示了可迁移的技巧：用触觉和温度替代视觉（盲人角色），用简短对白推进冲突与张力，用内心独白增加幽默与人物深度，并通过‘清心咒’与性行为的对比营造独特氛围。场景完整，情绪控制得当，对白节奏明快，适合作为言情小说亲密场景的参考。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 3.5, "distinctiveness": 3.5, "prose_quality": 3.5, "reference_value": 4.0, "scene_completeness": 4.5, "technique_value": 4.0}, "reference_reason": "该场景在亲密场景写作上展示了可迁移的技巧：用触觉和温度替代视觉（盲人角色），用简短对白推进冲突与张力，用内心独白增加幽默与人物深度，并通过‘清心咒’与性行为的对比营造独特氛围。场景完整，情绪控制得当，对白节奏明快，适合作为言情小说亲密场景的参考。", "reference_score": 3.8, "reference_status": "selected"}'::jsonb, '黎泱与泰诺在卧室亲密互动。泰诺解开她湿衣，用衬衫裹住并擦拭后背，提醒她吹干头发。黎泱主动求欢，泰诺要求她先解决两个女人，但黎泱坚持此刻。两人发生关系，泰诺戴耳机听清心咒，形成反差。最终在窗边结束，黎泱关窗又因热浪重开。', '细腻的感官描写与心理活动交织，动作与对话推进节奏，反差幽默（清心咒与情事）增强张力，短句与口语化表达使场景生动，适合学习情欲场景的含蓄与人物性格塑造。', '适合参考情欲场景的张力营造、心理与动作结合、反差幽默；避免过度直白或脱离人物性格的描写。', ARRAY['romance', 'emotional']::text[], ARRAY['romance', 'emotional']::text[], ARRAY['sensory_detail', 'contrast', 'inner_monologue', 'show_dont_tell']::text[], ARRAY['sensory_detail', 'contrast', 'inner_monologue', 'show_dont_tell']::text[], ARRAY['cinematic', 'colloquial', 'humorous', 'short_sentence']::text[], ARRAY['cinematic', 'colloquial', 'humorous', 'short_sentence']::text[], ARRAY['tension', 'sweetness', 'excitement']::text[], ARRAY['tension', 'sweetness', 'excitement']::text[], ARRAY['window', 'night', 'fire']::text[], ARRAY['window', 'night', 'fire']::text[], 'advance', '{"emotion_tags": ["tension", "sweetness", "excitement"], "key_images": ["window", "night", "fire"], "narrative_func": "advance", "scene_type": ["romance", "emotional"], "style_summary": "细腻的感官描写与心理活动交织，动作与对话推进节奏，反差幽默（清心咒与情事）增强张力，短句与口语化表达使场景生动，适合学习情欲场景的含蓄与人物性格塑造。", "style_tags": ["cinematic", "colloquial", "humorous", "short_sentence"], "summary": "黎泱与泰诺在卧室亲密互动。泰诺解开她湿衣，用衬衫裹住并擦拭后背，提醒她吹干头发。黎泱主动求欢，泰诺要求她先解决两个女人，但黎泱坚持此刻。两人发生关系，泰诺戴耳机听清心咒，形成反差。最终在窗边结束，黎泱关窗又因热浪重开。", "technique": ["sensory_detail", "contrast", "inner_monologue", "show_dont_tell"], "usage_hint": "适合参考情欲场景的张力营造、心理与动作结合、反差幽默；避免过度直白或脱离人物性格的描写。"}'::jsonb, 'annotated', 'indexed', NULL, 1, TRUE, '2026-10-01T07:15:24.455781+00:00', '2026-10-01T08:01:42.585516+00:00');
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at") OVERRIDING SYSTEM VALUE VALUES (891, 44, 21, 14, 14, '翌日早上。

阿义前脚刚迈入庄园，就被泰诺叫了过去。

“对她的训练暂停。”

阿义愣了一下:“为什么啊老板？她的基础很差。”

墨镜挡住了泰诺的眼眸，阿义分不清那里面有没有笑意，只看见老板露出的手臂和脖子，又有好几条抓痕。

“这不重要。你先帮我找两个女人进庄园，就说是塔丽娜那边送来的。”

泰诺顿了顿，补充道:“不用漂亮，相貌普通的。”

阿义张了张嘴，然后应下。

他跟在泰诺身边多年，知道什么时候该问，什么时候不该问。

“还有，”泰诺递给阿义一杯牛奶。

“拿去给她。”

阿义沉默了两秒，走过去接过杯子。

泰诺:“……亲自。”

阿义拿着牛奶，困住了脚步。

自己是老板的助理，她只是一个来历不明的女仆，一个泡茶的，凭什么？

泰诺:“有问题？”

阿义:“没有，老板。”

墨镜下的唇勾起:“欺负人不要欺负得太明显，况且……还是我的人。”

阿义惶恐:“老板，我……”

“去吧。”泰诺压下了唇角，终止了谈话。

阿义端着牛奶走在走廊里，眉头拧成一个疙瘩。

他召来了女仆，让女仆给那个可以碰老板的女人送去。

可不管女仆怎么敲门，房间里的黎泱就是不肯开门。

阿义没辙，只好重新端上牛奶，亲自去敲门。

他敲了半天，黎泱才姗姗来迟。

打开门后，阿义看着那张极其平庸的脸，更加不懂自己那位丰神俊逸的老板这么宠这个一无是处的女人。

“老板让你喝了它。”阿义把牛奶怼到黎泱面前。

黎泱连眼皮也不抬一下，指尖触了触杯身便说:“凉了，不喝。”

她正想关门，被阿义脚一伸，挡住了即将关上的门缝。

“老板让你喝了它。”阿义加重了语气，透着不耐烦。

黎泱:“我乳糖不耐受，喝凉的牛奶会在你老板面前放屁。”

阿义鄙夷地看着黎泱，却不知道该怎么反驳。仿佛这女人的意思是，她一旦在老板面前放屁……

她就会把这口屁算他头上。

黎泱打了个哈欠，毫不在意地说道:

“你怕先生责备，你就自己处理掉它，我不供你出来就是了。”

说完，往阿义的脚上一踩，趁阿义吃痛，“砰”地一声关上了门。

黎泱看向房间里唯一一盆绿植。

根已经烂透，枝叶也全部枯萎，无法再容纳一杯牛奶。

等她改日换一盆新的再说吧。

五天后。

阿义领着两位女郎，大摇大摆地来到黎泱面前。

阿义嘚瑟地昂着头:“她们，是塔丽娜夫人送来的，会留在庄园，和你一样侍候老板。”

黎泱扫了一眼，觉得这两个女郎，和易容后的自己有点像，便问阿义:

“这次送来的颜值怎么这么低？”

阿义嫌弃:“你懂什么？老板就好这一口。”

黎泱:“然后呢？你把人带到我这来干什么？”

阿义:“老板说，交给你来安排。”

黎泱想起，泰诺之前交待的任务——杀一个，放一个。

呵～这男人真得很阴。

到底杀哪个，他把决定权给了她。这比直接让她杀两个更难。

因为自己的选择，决定了一个人的生死，这会让人更有负罪感。

黎泱找了个房间，先让这两个女郎安顿下来。

她不想伤及无辜，打算从长计议。

可有的人却等不及。', 1128, 'time_or_place_boundary', FALSE, 'selected', 3.8, '该场景在有限篇幅内完成了多重叙事功能：通过抓痕等细节暗示人物关系，用对白展现权力博弈与人物性格，以“牛奶冲突”和“杀一放一”的任务设计制造冲突与悬念，结尾留白有效。对白节奏、动作调度和情绪控制具有可迁移的写作参考价值，虽语言偏网文风格，但技巧明确，值得学习。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 3.5, "distinctiveness": 3.5, "prose_quality": 3.5, "reference_value": 4.0, "scene_completeness": 4.0, "technique_value": 4.0}, "reference_reason": "该场景在有限篇幅内完成了多重叙事功能：通过抓痕等细节暗示人物关系，用对白展现权力博弈与人物性格，以“牛奶冲突”和“杀一放一”的任务设计制造冲突与悬念，结尾留白有效。对白节奏、动作调度和情绪控制具有可迁移的写作参考价值，虽语言偏网文风格，但技巧明确，值得学习。", "reference_score": 3.8, "reference_status": "selected"}'::jsonb, '泰诺暂停对黎泱的训练，命阿义找两名相貌普通的女子送入庄园，并亲自给黎泱送牛奶。黎泱以乳糖不耐受为由拒绝，踩阿义脚关门。五天后，阿义带两名女郎见黎泱，称是塔丽娜所送、由黎泱安排。黎泱想起泰诺“杀一个放一个”的任务，陷入选择困境，打算从长计议，但有人等不及。', '通过助理阿义的受限视角与简短对话，层层递进展现泰诺的阴鸷掌控与黎泱的机敏反抗；牛奶、绿植等细节暗藏人物关系与处境，结尾以“杀一放一”的道德困境和“有人等不及”制造悬念，节奏张弛有度。', '适合参考用日常道具（牛奶、绿植）承载权力博弈与伏笔，借配角视角侧写主角；避免过度解释人物动机，让对话和动作自行呈现。', ARRAY['dialogue_conflict', 'daily_life', 'emotional']::text[], ARRAY['dialogue_conflict', 'daily_life', 'emotional']::text[], ARRAY['contrast', 'foreshadow', 'hook', 'show_dont_tell']::text[], ARRAY['contrast', 'foreshadow', 'hook', 'show_dont_tell']::text[], ARRAY['colloquial', 'dark', 'humorous', 'restrained', 'short_sentence']::text[], ARRAY['colloquial', 'dark', 'humorous', 'restrained', 'short_sentence']::text[], ARRAY['tension', 'fear', 'anger']::text[], ARRAY['tension', 'fear', 'anger']::text[], ARRAY['door']::text[], ARRAY['door']::text[], 'cliffhanger', '{"emotion_tags": ["tension", "fear", "anger"], "key_images": ["door"], "narrative_func": "cliffhanger", "scene_type": ["dialogue_conflict", "daily_life", "emotional"], "style_summary": "通过助理阿义的受限视角与简短对话，层层递进展现泰诺的阴鸷掌控与黎泱的机敏反抗；牛奶、绿植等细节暗藏人物关系与处境，结尾以“杀一放一”的道德困境和“有人等不及”制造悬念，节奏张弛有度。", "style_tags": ["colloquial", "dark", "humorous", "restrained", "short_sentence"], "summary": "泰诺暂停对黎泱的训练，命阿义找两名相貌普通的女子送入庄园，并亲自给黎泱送牛奶。黎泱以乳糖不耐受为由拒绝，踩阿义脚关门。五天后，阿义带两名女郎见黎泱，称是塔丽娜所送、由黎泱安排。黎泱想起泰诺“杀一个放一个”的任务，陷入选择困境，打算从长计议，但有人等不及。", "technique": ["contrast", "foreshadow", "hook", "show_dont_tell"], "usage_hint": "适合参考用日常道具（牛奶、绿植）承载权力博弈与伏笔，借配角视角侧写主角；避免过度解释人物动机，让对话和动作自行呈现。"}'::jsonb, 'annotated', 'indexed', NULL, 1, TRUE, '2026-10-01T07:15:24.455781+00:00', '2026-10-01T08:01:42.585516+00:00');
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at") OVERRIDING SYSTEM VALUE VALUES (898, 44, 28, 19, 19, '第18章 金主要结婚了

“留个联系方式吧。”

被扯掉头套的黎泱说，“免得日后每次联系都被你们抬来抬去，怪麻烦的。”

“呵，你有没有日后也难说。”塔丽娜冷笑。

她拿起高脚红酒杯晃了晃，悠哉地说道:

“在你爬上我儿子床的那天，你就应该知道，你只是一个泄欲的工具，是不可能嫁进我们家的。”

黎泱冷嗤。

抱歉老女人，你搞反了，你儿子才是我泄欲的工具。

但黎泱能屈能伸，知道此刻不能硬刚，只能在心里的小本本里，画了一横。

塔丽娜:“我最近给他找了一门顶好的婚事，对方是华国宋家的小女儿，温婉甜美的黑道千金。”

婚事？

金主要结婚了，那她是不是也可以任务结束了？

做小三不好。

破坏别人的婚姻不好。

人民公仆不能干这种事。

回头，她要跟胡建明积极地汇报一下。

塔丽娜:“所以你是不可能永远留在他身边的，倒不如把我的事办好，拿着我给你的钱，找一个平庸的男人嫁了。”

可是，你给我的钱，都上缴上去，为国家建设做贡献了。

但黎泱也不能直说，只能搪塞道:

“不是芍药不想替夫人办事，只是先生对我有戒备，我进不去他的书房，所以才……”

“那我再给你三天的时间。”塔丽娜打断她，

“我用你确实比较方便，但也不是非你不可。我从不养废人。”

你才废人。

黎泱又在心里的小本本里，画了一竖。

塔丽娜抿了一口红酒，然后把酒缓缓倾倒在地上，像祭拜死人那样。

“再完成不了任务，下次你被绑就不是来见我，而是见阎王了。”

小本本里，又画上了一横。

所以绕了一圈，她黎泱还是得进书房装窃听器。

装完你的，装你的。

黎泱怎么都想不懂，一个深居简出的废子，怎么就这么多人惦记上了？

胡建明说要“埋伏”，塔丽娜说要“关心”。

只是黎泱咬断手指头也没想到——

惦记泰诺的，居然还有第三个人。', 688, 'chapter_start', FALSE, 'selected', 3.5, '该场景在有限篇幅内完成了冲突建立、人物性格展示、信息揭露和悬念收尾。对白与内心独白的反差制造了喜剧效果和人物张力，用“画小本本”具象化情绪累积，结尾以“第三个人”制造悬念钩子，这些手法具有可迁移的写作参考价值。虽然语言和桥段偏常规，但场景节奏、视角控制和冲突推进清晰，适合作为网文场景写作的参考。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 3.5, "distinctiveness": 3.0, "prose_quality": 3.0, "reference_value": 3.5, "scene_completeness": 4.0, "technique_value": 3.5}, "reference_reason": "该场景在有限篇幅内完成了冲突建立、人物性格展示、信息揭露和悬念收尾。对白与内心独白的反差制造了喜剧效果和人物张力，用“画小本本”具象化情绪累积，结尾以“第三个人”制造悬念钩子，这些手法具有可迁移的写作参考价值。虽然语言和桥段偏常规，但场景节奏、视角控制和冲突推进清晰，适合作为网文场景写作的参考。", "reference_score": 3.5, "reference_status": "selected"}'::jsonb, '塔丽娜当面羞辱黎泱，称她只是泰诺的泄欲工具，并宣布已为泰诺安排宋家千金婚事。黎泱表面周旋、内心吐槽，得知金主结婚或可结束任务。塔丽娜限她三天进书房装窃听器，否则下次见面就是阎王。结尾暗示，惦记泰诺的还有第三个人。', '对话紧凑推进信息，内心独白以吐槽消解黑道威胁，形成冷峻与幽默的反差；短句快节奏，结尾用“第三个人”制造悬念钩子，适合学习冲突场景的节奏与人物塑造。', '适合参考高压对话中夹内心吐槽、用反差塑造人物、结尾留钩。避免吐槽过密削弱威胁感，或让信息全靠对白直给。', ARRAY['dialogue_conflict', 'mystery', 'emotional']::text[], ARRAY['dialogue_conflict', 'mystery', 'emotional']::text[], ARRAY['inner_monologue', 'contrast', 'escalation', 'hook']::text[], ARRAY['inner_monologue', 'contrast', 'escalation', 'hook']::text[], ARRAY['colloquial', 'dark', 'fast_paced', 'humorous', 'short_sentence']::text[], ARRAY['colloquial', 'dark', 'fast_paced', 'humorous', 'short_sentence']::text[], ARRAY['tension', 'anger', 'fear']::text[], ARRAY['tension', 'anger', 'fear']::text[], ARRAY['blood', 'door']::text[], ARRAY['blood', 'door']::text[], 'cliffhanger', '{"emotion_tags": ["tension", "anger", "fear"], "key_images": ["blood", "door"], "narrative_func": "cliffhanger", "scene_type": ["dialogue_conflict", "mystery", "emotional"], "style_summary": "对话紧凑推进信息，内心独白以吐槽消解黑道威胁，形成冷峻与幽默的反差；短句快节奏，结尾用“第三个人”制造悬念钩子，适合学习冲突场景的节奏与人物塑造。", "style_tags": ["colloquial", "dark", "fast_paced", "humorous", "short_sentence"], "summary": "塔丽娜当面羞辱黎泱，称她只是泰诺的泄欲工具，并宣布已为泰诺安排宋家千金婚事。黎泱表面周旋、内心吐槽，得知金主结婚或可结束任务。塔丽娜限她三天进书房装窃听器，否则下次见面就是阎王。结尾暗示，惦记泰诺的还有第三个人。", "technique": ["inner_monologue", "contrast", "escalation", "hook"], "usage_hint": "适合参考高压对话中夹内心吐槽、用反差塑造人物、结尾留钩。避免吐槽过密削弱威胁感，或让信息全靠对白直给。"}'::jsonb, 'annotated', 'indexed', NULL, 1, TRUE, '2026-10-01T07:15:24.455781+00:00', '2026-10-01T08:01:42.585516+00:00');
