INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at") OVERRIDING SYSTEM VALUE VALUES (1014, 44, 144, 99, 99, '第98章 老娘我不想干了

黎泱又一次登上了那艘船。

泰诺带着她，从另外一条通道进入十六层会所。

上一次，黎泱瞒着泰诺偷偷进来，可如今，这艘船是塔丽娜的。

打开门，黎泱就感觉到了不一样。

这里的一切都被金钱、暴力、性欲泡烂了。

男人们穿着高昂的西装，上半身衣冠楚楚，手里端着香槟或雪茄。

可下半身，赤裸的。

游走的女人不再是矜贵的，她们穿着性感穿梭在男人之间。有的甚至一丝不挂。

她们不是观众，她们只是男人们用下半身消遣的对象。

没有人觉得这有什么不对，男人的笑声和香槟的气泡一样轻盈。

而赛台上，变成了一个巨大的玻璃箱。

那是一个密封的玻璃盒。

盒子里装着十几个正互相撕咬的男人，脚下踩着已经倒下的尸体，一层叠一层，像被随意堆放的货物。

四面玻璃早已被血浸透，凝固成深浅交错的暗红色块。那些喊叫和撞击被封在玻璃之内，被压成闷响。

这时，观众席上传来异动。

一群男人在捉拿一个女人。

那个女人留着齐刘海，巴掌大的脸上扑闪着一双圆圆的眼睛。

看上去，这个女人与船上其他沾满风尘的女人不同，她像是个养尊处优的富家千金。

可那些壮汉并不怜香惜玉，一个个出手狠厉，接连砸出几拳，一拳比一拳快。

那女人灵巧闪躲，但越来越吃力。

她旁边，一个男人倚着栏杆，悠闲地双手环胸，隔岸观火。

这男人长得很带劲，眼神一刻都没离开那女人，但就是不出手帮忙。

这男人，这不就是黎泱的大湾区销售经理吗？

所以，他身旁这个女人就是……

“先生……”黎泱朝着泰诺开口，“您的未婚妻被你手下的人欺负，不打算出手帮一下吗？”

她凑在泰诺耳边低语。

而泰诺只是侧脸、低头，趁机吻了吻黎泱的唇。

泰诺:“你要我出手吗？”

黎泱不假思索：“要。”

“听你的。”泰诺挥挥手，安排了身旁的黑衣男子过去，处理那场闹剧。

“还想看吗？”泰诺问道。

黎泱没有回答，另起一个话题：“这里变化为什么这么大？”

“变化？你不是第一次来？”泰诺在浅笑。

黎泱面不改色：“上次来，听人说起，这里就是一个搏击场而已。可现在……”

乌烟瘴气。

黎泱都懒得说了。

泰诺在一旁，却很淡定：“所有事情都不会一成不变。”

人和事在变，承诺也会变。

黎泱看着眼前的迷乱和血腥，别开了脸：“不想看了。”

“好。”泰诺握着她的手离开。', 885, 'chapter_start', FALSE, 'selected', 3.8, '该场景在氛围营造、对话潜台词、权力关系展示和悬念设置上具有可迁移的写作技巧。开篇用密集的感官细节快速建立奢靡、暴力、性欲交织的异化空间，并通过黎泱的视角对比“上次”与“如今”，暗示人物处境与关系变化。对话简洁但信息量大：黎泱点破泰诺未婚妻被手下欺负，泰诺以吻回应并问“你要我出手吗”，既展现亲密与权力博弈，又推进情节。结尾“所有事情都不会一成不变”与“承诺也会变”形成主题回响，留白得当。虽然部分人物关系依赖前文，但作为独立场景仍完整且对白节奏、冲突调度、情绪控制有参考价值。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 3.5, "distinctiveness": 3.5, "prose_quality": 4.0, "reference_value": 4.0, "scene_completeness": 4.5, "technique_value": 4.0}, "reference_reason": "该场景在氛围营造、对话潜台词、权力关系展示和悬念设置上具有可迁移的写作技巧。开篇用密集的感官细节快速建立奢靡、暴力、性欲交织的异化空间，并通过黎泱的视角对比“上次”与“如今”，暗示人物处境与关系变化。对话简洁但信息量大：黎泱点破泰诺未婚妻被手下欺负，泰诺以吻回应并问“你要我出手吗”，既展现亲密与权力博弈，又推进情节。结尾“所有事情都不会一成不变”与“承诺也会变”形成主题回响，留白得当。虽然部分人物关系依赖前文，但作为独立场景仍完整且对白节奏、冲突调度、情绪控制有参考价值。", "reference_score": 3.8, "reference_status": "selected"}'::jsonb, '黎泱随泰诺再登船进入十六层会所，目睹被金钱、暴力、性欲浸透的堕落场景：玻璃箱内男人互相撕咬，观众席上壮汉围攻一名富家千金模样的女子，而泰诺的销售经理在旁冷眼旁观。黎泱认出女子是泰诺未婚妻，问泰诺是否出手，泰诺吻她后答应。黎泱问变化原因，泰诺答“所有事情都不会一成不变”，黎泱不想再看，两人离开。', '通过感官细节与强烈对比（衣冠楚楚的上半身与赤裸下半身、玻璃箱内血腥与观众席悠闲）营造压抑氛围，用简短对话推进人物关系与悬念，动作与心理描写克制，画面感强。', '适合参考如何用场景描写暗示权力与堕落，用对话制造暧昧与冲突；避免过度渲染暴力色情，注意节奏与留白。', ARRAY['dialogue_conflict', 'emotional', 'action']::text[], ARRAY['dialogue_conflict', 'emotional', 'action']::text[], ARRAY['contrast', 'sensory_detail', 'show_dont_tell', 'foreshadow']::text[], ARRAY['contrast', 'sensory_detail', 'show_dont_tell', 'foreshadow']::text[], ARRAY['cinematic', 'dark', 'restrained', 'short_sentence']::text[], ARRAY['cinematic', 'dark', 'restrained', 'short_sentence']::text[], ARRAY['tension', 'anger', 'sweetness']::text[], ARRAY['tension', 'anger', 'sweetness']::text[], ARRAY['blood', 'door', 'window']::text[], ARRAY['blood', 'door', 'window']::text[], 'advance', '{"emotion_tags": ["tension", "anger", "sweetness"], "key_images": ["blood", "door", "window"], "narrative_func": "advance", "scene_type": ["dialogue_conflict", "emotional", "action"], "style_summary": "通过感官细节与强烈对比（衣冠楚楚的上半身与赤裸下半身、玻璃箱内血腥与观众席悠闲）营造压抑氛围，用简短对话推进人物关系与悬念，动作与心理描写克制，画面感强。", "style_tags": ["cinematic", "dark", "restrained", "short_sentence"], "summary": "黎泱随泰诺再登船进入十六层会所，目睹被金钱、暴力、性欲浸透的堕落场景：玻璃箱内男人互相撕咬，观众席上壮汉围攻一名富家千金模样的女子，而泰诺的销售经理在旁冷眼旁观。黎泱认出女子是泰诺未婚妻，问泰诺是否出手，泰诺吻她后答应。黎泱问变化原因，泰诺答“所有事情都不会一成不变”，黎泱不想再看，两人离开。", "technique": ["contrast", "sensory_detail", "show_dont_tell", "foreshadow"], "usage_hint": "适合参考如何用场景描写暗示权力与堕落，用对话制造暧昧与冲突；避免过度渲染暴力色情，注意节奏与留白。"}'::jsonb, 'annotated', 'indexed', NULL, 1, TRUE, '2026-10-01T07:15:24.455781+00:00', '2026-10-01T08:01:42.585516+00:00');
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at") OVERRIDING SYSTEM VALUE VALUES (1067, 44, 197, 128, 128, '二十岁的时候，黎泱在学校里打架，把人的牙给打崩了。

她被学校记了一次过。

二十一岁的时候，她又参加了一次群架。准确的说，是她一个人挑了十个人。

这一次，她被学校勒令退学，在校门口，遇到了胡建明。

如今二十六岁的黎泱，第二次站在了黎先勇的墓前。

除了她以外，墓前居然还有一个人的身影。', 136, 'rule', FALSE, 'archived', 2.8, '该场景以年龄节点快速概述人物前史，并在结尾用‘居然’设置悬念，属于有效的时间跳跃与信息交代。但整体缺乏具体场景展开、对白、动作调度或独特技法，可迁移的写作参考价值有限，更适合归档。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 3.0, "distinctiveness": 2.5, "prose_quality": 3.5, "reference_value": 2.8, "scene_completeness": 2.5, "technique_value": 3.0}, "reference_reason": "该场景以年龄节点快速概述人物前史，并在结尾用‘居然’设置悬念，属于有效的时间跳跃与信息交代。但整体缺乏具体场景展开、对白、动作调度或独特技法，可迁移的写作参考价值有限，更适合归档。", "reference_score": 2.8, "reference_status": "archived"}'::jsonb, '', '', '', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], '', '{}'::jsonb, 'not_applicable', 'not_applicable', NULL, 1, TRUE, '2026-10-01T07:15:24.455781+00:00', '2026-10-01T08:01:42.585516+00:00');
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at") OVERRIDING SYSTEM VALUE VALUES (945, 44, 75, 57, 57, '第56章 酒后乱性，可以！

黎泱看着他，看着他那副醉意朦胧的样子。

“看来先生醉得不轻，您还是早点休息吧。”

这是她的回答。

而落在泰诺不太清醒的认知里，他们两人的对话是这样的——

泰诺自己:【接吻吗？】

芍药回答:【你一边歇着去。】

泰诺的眉峰不经意聚拢在一起。

而黎泱权当他是喝醉了，没怎么放心上，起身。

沙发的一团忽然恢复了弹性，泰诺伸手一抓，刚好扣住了黎泱纤细的手腕。

手一用力，把黎泱扯入自己滚烫的怀里，让她重新陷在沙发上。

“不可以。”他硬邦邦地吐出这三个字。

黎泱困惑:“什么不可以？”

泰诺指尖捏着黎泱的下巴，迫使她抬头，唇与唇之间的距离很近:

“不是说，陪我玩游戏吗？你怎么可以中途退出？”

灼热的气息洒在黎泱的脸上，带着酒的微醺热度。

“你难道也要像他们那样，说好了游戏开始，却把我一个人丢在那里吗？”

黎泱挑眉:“先生提的这个要求，算哪门子游戏？”

“怎么不算游戏？”泰诺不急不缓地说:“真心话与大冒险。”

黎泱没想到会是这个答案，窝在男人怀里的她发出一声嗤笑:

“那您说说看，和我接吻，算是真心话，还是大冒险？”

捏着她下巴的拇指，摩挲了两下，泰诺说道:“大冒险。”

对，不是真心话。

他是这样想的。

她也是这样想的。

黎泱的笑意未褪，她抬起指尖，温凉的指腹压在男人的唇上，似有若无地来回描绘着。

酒意染得他薄唇嫣红，比女人还美。

这男人，确实诱人。

谁能拒绝这副皮囊？

黎泱的身体贴上了他，感受到他因醉酒的滚烫。

“先生……您是第一次喝醉吗？”黎泱的声音变得轻柔，便也多了几分缱绻。

泰诺沉沉一声:“嗯。”他的意识似乎只残存最后一丝清醒。

黎泱:“在我面前醉酒，就不怕我乱来？”

黎泱的乱来，可不是指肉体上的。

她在查他，他在防她。

可他如今却毫不忌讳地醉在她面前。

就像一头猛兽在猎人面前，露出了肚皮。

泰诺没有回话，只是垂着长长的睫毛，弯起了唇角。

连眼角也微微泛着红，太魅惑了。

黎泱的指尖就停在他的唇珠上，搭着他柔软的下唇:“那您明早醒来，会断片吗？我需要对您负责吗？”

泰诺依旧不语，酒精侵蚀着他每一个细胞。

他仿佛放弃了抵抗，头突然无力垂落，带着一股无形的力靠近，让黎泱的唇，触到她淡粉色的指甲盖。

而另一边，是指腹抵着唇。

食指指尖，成为两人唯一一道障碍。

泰诺握上她的手腕，想挪开这道障碍……

而黎泱却先一步推开了他。

“可惜我们之间，酒后乱性，可以。乱其他，不行。”

黎泱给今晚的涟漪，来了个盖棺定论。

泰诺被推倒在沙发上，彻底被酒精吞噬，合上了他沉重的眼皮。

不知道有没有把黎泱最后这句话，听了进去。

算了，也许第二天醒来，他压根什么都不记得。

番茄小说里，基本都是这种套路。

黎泱看了他一眼，便从沙发上起来。

接吻，是两个人的事。

既然一个人在耍酒疯，那么另外一个，得保持着清醒。

她清醒地记得自己的身份；

也清醒地知道自己的任务；

更是清醒地坚信，她不可以动心。

飞鸟和鱼，怎么相爱？', 1158, 'chapter_start', FALSE, 'selected', 3.8, '该场景在醉酒暧昧互动中展现了可迁移的写作技巧：利用醉酒者主观认知与客观对话的错位制造幽默与张力；通过指尖、唇、手腕等物理细节表现情感克制与推拉；用‘猛兽露出肚皮’‘飞鸟和鱼’等比喻点明人物关系与立场；对白有潜台词和双关，节奏紧凑。场景完整，有起承转合，且能在有限篇幅内交代人物动机（她在查他、他在防她、她不可动心）。虽属常见言情套路，但技术细节对写作者有参考价值。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 3.5, "distinctiveness": 3.2, "prose_quality": 4.0, "reference_value": 4.0, "scene_completeness": 4.5, "technique_value": 4.2}, "reference_reason": "该场景在醉酒暧昧互动中展现了可迁移的写作技巧：利用醉酒者主观认知与客观对话的错位制造幽默与张力；通过指尖、唇、手腕等物理细节表现情感克制与推拉；用‘猛兽露出肚皮’‘飞鸟和鱼’等比喻点明人物关系与立场；对白有潜台词和双关，节奏紧凑。场景完整，有起承转合，且能在有限篇幅内交代人物动机（她在查他、他在防她、她不可动心）。虽属常见言情套路，但技术细节对写作者有参考价值。", "reference_score": 3.8, "reference_status": "selected"}'::jsonb, '泰诺醉酒，将黎泱的拒绝误读为游戏回应。他扣住她手腕，要求继续“真心话与大冒险”，并选“大冒险”为接吻。黎泱以指尖抵住他唇，暧昧试探后推开他，定论“酒后乱性可以，乱其他不行”。她清醒自知任务在身，告诫自己不可动心。泰诺醉倒，不知是否听见。飞鸟与鱼，如何相爱？', '以醉酒与清醒的对比贯穿，用灼热气息、指尖触感等感官细节和内心独白，在暧昧互动中展现人物立场与情感张力。对话与动作结合，节奏张弛有度，结尾以比喻点题，余味悠长。', '适合参考醉酒暧昧戏的张力控制、对比手法和内心独白。避免过度依赖“套路”式自嘲，需保持人物动机清晰，防止情感转折生硬。', ARRAY['romance', 'emotional', 'dialogue_conflict']::text[], ARRAY['romance', 'emotional', 'dialogue_conflict']::text[], ARRAY['contrast', 'sensory_detail', 'inner_monologue', 'show_dont_tell']::text[], ARRAY['contrast', 'sensory_detail', 'inner_monologue', 'show_dont_tell']::text[], ARRAY['cinematic', 'lyrical', 'restrained', 'short_sentence']::text[], ARRAY['cinematic', 'lyrical', 'restrained', 'short_sentence']::text[], ARRAY['tension', 'sweetness', 'heartache']::text[], ARRAY['tension', 'sweetness', 'heartache']::text[], ARRAY['fire']::text[], ARRAY['fire']::text[], 'advance', '{"emotion_tags": ["tension", "sweetness", "heartache"], "key_images": ["fire"], "narrative_func": "advance", "scene_type": ["romance", "emotional", "dialogue_conflict"], "style_summary": "以醉酒与清醒的对比贯穿，用灼热气息、指尖触感等感官细节和内心独白，在暧昧互动中展现人物立场与情感张力。对话与动作结合，节奏张弛有度，结尾以比喻点题，余味悠长。", "style_tags": ["cinematic", "lyrical", "restrained", "short_sentence"], "summary": "泰诺醉酒，将黎泱的拒绝误读为游戏回应。他扣住她手腕，要求继续“真心话与大冒险”，并选“大冒险”为接吻。黎泱以指尖抵住他唇，暧昧试探后推开他，定论“酒后乱性可以，乱其他不行”。她清醒自知任务在身，告诫自己不可动心。泰诺醉倒，不知是否听见。飞鸟与鱼，如何相爱？", "technique": ["contrast", "sensory_detail", "inner_monologue", "show_dont_tell"], "usage_hint": "适合参考醉酒暧昧戏的张力控制、对比手法和内心独白。避免过度依赖“套路”式自嘲，需保持人物动机清晰，防止情感转折生硬。"}'::jsonb, 'annotated', 'indexed', NULL, 1, TRUE, '2026-10-01T07:15:24.455781+00:00', '2026-10-01T08:01:42.585516+00:00');
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at") OVERRIDING SYSTEM VALUE VALUES (1081, 44, 211, 138, 138, '黎泱穿着一身警服，站在黎先勇的墓前。

那枚警号别在胸前，在夕阳下泛着细碎的光。

同样是一身警服的阿兰站在她身旁:“下个月我要结婚了。”

黎泱:“恭喜你。”

阿兰:“有空的话，来陪我喝一杯吧。”

黎泱点了点头，眼里蒙上一层雾：“好。一言为定。”

夕阳正沿着墓园的方向缓慢地沉落，把那些碑面的轮廓染成一片温暖的金色。

每一块碑都安静地立着，都代表着一段可歌可泣的感人事迹。

黎泱捧着两束花，一个人站在墓园里。

她把其中一束轻轻放在黎先勇的碑前，没有多余的装饰，花茎被修剪得很整齐。

身后传来脚步声，黎泱回头，是泰诺来接她。

“这么早的飞机？”黎泱问。

“想你。”泰诺自然地把她拢入怀里，“再过半年，等我把集团业务的核心全部移到华国，我就不用跑来跑去了。”

“我家先生辛苦了。”黎泱弯起了眼睛，笑意盈盈地看向他。

“没办法，谁叫你以后上班出入境管得这么严，只能是我朝你跑来，我的黎大警官。”

泰诺低头，吻了吻她的额。

黎泱笑着，没再说话。

泰诺:“走吧？”

“嗯。”

黎泱把另外一束花，放在旁边的墓碑上。

和泰诺，结伴离开。

【正文完】

番外1 初见

昏黄的灯，缠绵的吻。

泰诺把黎泱抵在沙发的角落里，俯身亲吻着她。

他刚应酬完回来，西装还没换，领带已经扯松了。

身下的人，一套粉粉的萌萌的居家服也凌乱了，又纯又欲。

泰诺为了迁就年薪20万的黎泱，放下缅城几百亿的生意，在帝都买了一套大平层。

他跟黎泱说过两次“以后我们住这儿”，她每次都只是“嗯”一声，没有多接。

泰诺就当做是两人同居的开始。

都同居了，那还不算未婚夫妻吗？

是的，他的观念很保守的。

答应同居，就是相当于黎泱答应嫁给他。

今晚，他有个应酬，喝了一点酒，进门的时候黎泱正坐在沙发上翻一摞文件。

他走过去，弯下腰把人捞进怀里，黎泱没有推开他，任由他的吻落下。

过了一会儿，黎泱偏开脸：“好了，够了。”

她微微喘着气，唇色比平时鲜艳一些。

“不够。”泰诺又压了下来。

这回，黎泱兀地一下抵住他的胸口，皱着眉打量他：

“泰诺·帕恩，你是不是有什么事情瞒着我？”

泰诺心里一沉，那枚私人定制的求婚戒指，珠宝店说还要三天才能送到。

她是怎么发现的？

黎泱捏着他的下巴，微微眯着眼：“之前你答应过我什么？”

泰诺握住她的手，把她的指腹拢进自己掌心里，拇指沿着她的手背边缘慢慢摩挲：

“我答应过你，接下来的余生都不会骗你。”

黎泱没有抽回手：“既然这样，你就老实招了。”

泰诺看着在自己怀里娇媚的她，琢磨着该怎么开口。

他认为，虽然黎泱已经同意跟他结婚，但是求婚的仪式这么浪漫……

怎么都要给自己来一个。

可还有很多细节都没完全敲定，他打算等一切确认好了再告诉她，而不是让她通过自己今晚的异常表现来推断。

他尝试谈判：“黎泱，能不能给我一点空间，我……”

“不行。你必须坦白招了，你老实告诉我……”黎泱睨着他。

“你以前那套会哄还会停，是不是都是装的？实际上你就是一个重欲的人。”

泰诺:“……”

黎泱:“一个月，你就只消停七天！”

泰诺:“……”

黎泱推开他，收拾一下，拿起茶几上的资料骂骂咧咧朝书房走去。

突然一个失重，资料散了一地，黎泱被腾空抱起，被迫往卧室里拐去。

泰诺把黎泱放在床上，脱掉外套，就俯身压住了她。

床深深地凹陷。

泰诺:“以前有清心咒，我能控制自己的欲望。”

黎泱:“现在怎么就不控制了？”

泰诺手肘在她一侧，撑着上半身，看着身下的她，说道:

“以前塔丽娜总是会给我送女人，我怕自己沉迷在姓艾里，更怕自己沉迷在你身上，所以每一次都会听清心咒，试图把这种欲望从自己的身上剥离开来……

“可现在我不需要这么做了，我可以放纵自己在你的世界里。因为，你是不会丢下我的，对吗？”

说完，他俯身又吻住了她。

一个大男人把话说成这样，黎泱的心忽然就软了。

她抬手圈住他的脖子，迎上他的吻。

身上那套粉色的小猫咪居家服被他不紧不慢地褪下来，落在床边。

可他的手指刚触到她肩带边缘，黎泱忽然停住了。

“等一下……”她偏开头，声音带着一丝还没完全平复的气息，“所以你是把我当成塔丽娜送你的女人一样？”

泰诺:“……？？……从来没有。”

黎泱歪着头，疑惑地看他:“你是有洁癖的，为什么我当初就能把你上了呢？”

泰诺气笑:“关于这一点，你不是应该比我更清楚么？”

黎泱皱眉，有三分生气:“该不会洁癖也是你在装的？不然，怎么一个禁欲又洁癖的人，揪着一个相貌平平的女佣不放？”

泰诺的笑意更深:“你知道以前，我为什么喜欢跟你做吗？”

黎泱:“你有需求。”

泰诺:“不，是因为那时的你，只有在床上的时候，对我才是真的。”

被说中的黎泱死鸭子嘴硬:“不，你错了，数据统计80%的女人在床上都是演的。”

泰诺:“你是那20%，我知道。”

被说中的黎泱，嘴更硬了，只吐出四个字:“迷之自信。”

她想起身下床，却被泰诺抓住脚踝，一把扯到他身下。

这次，他不再给她拒绝的机会，欺身压了下来。

“湿了就算你输。”

嗯……

黎泱很快就输了。', 1948, 'rule', FALSE, 'archived', 2.8, '该场景包含正文结局与番外，虽在对话节奏、悬念设置、亲密场景中的信息揭露和情绪控制上有一定可迁移性，但整体属于常见网络言情套路，语言平实，技法不够突出，且高度依赖前文人物关系与设定，独立参考价值有限，因此归档。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 2.5, "distinctiveness": 2.5, "prose_quality": 3.0, "reference_value": 2.8, "scene_completeness": 4.0, "technique_value": 3.0}, "reference_reason": "该场景包含正文结局与番外，虽在对话节奏、悬念设置、亲密场景中的信息揭露和情绪控制上有一定可迁移性，但整体属于常见网络言情套路，语言平实，技法不够突出，且高度依赖前文人物关系与设定，独立参考价值有限，因此归档。", "reference_score": 2.8, "reference_status": "archived"}'::jsonb, '', '', '', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], '', '{}'::jsonb, 'not_applicable', 'not_applicable', NULL, 1, TRUE, '2026-10-01T07:15:24.455781+00:00', '2026-10-01T08:01:42.585516+00:00');
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at") OVERRIDING SYSTEM VALUE VALUES (949, 44, 79, 60, 60, '第59章 长得像个娘们似的

黎泱穿着一条低调古板的黑色连衣裙，从衣帽间出来，在化妆镜前，简单地画了个淡妆。

“不用我送你的香水吗？”泰诺依旧坐在窗边的餐桌前，餐桌上的食物，没怎么动。

“不了，其实我没有喷香水的习惯。”

黎泱在那对钻石耳环旁，挑上一对自己99元网购的普通耳钉戴上。

“而且，太贵重的东西，还是不太适合我。”

她对着镜子照了照，很满意自己这副简约的打扮。

泰诺没有说话，手中的刀叉虚拿着，人却没什么食欲。

黎泱丝毫没在意，简单收拾了一下化妆台，最后挽着一个小挎包离开。

门关上，房间里只留下她一地的贴身衣物。

泰诺放下手中的刀叉，靠在椅背上。

宿醉使他头疼，完全无法思考。

他第一次将自己放在一个意识丧失的处境，这很危险，甚至不可理喻。

自从和她在一起，他就有越来越多的不可理喻，包括昨晚那个梦。

与其说那是一个梦，倒不如说，是尘封好多年的记忆，再一次出现。

他已经很久没梦见小时候那个孤独无助的自己了。

在梦里，他被一群野孩子推倒在地，怀里紧紧抱着一只奄奄一息的狸花猫。

“道歉！我让你跟它道歉。”

褐灰色的眼眸镶在他稚嫩的脸上，精致得像个洋娃娃。

可那双无法聚焦的眼眸，却布满着愤恨。

“我呸！你以为你家有钱了不起啊？住大别墅了不起啊？！不就一只流浪猫吗？你跟畜生当朋友是你的事，凭什么让我跟一个畜生道歉？！”

为首的胖子故意捏着嗓音讲话。

“我不会放过你们的！”瘦弱的小泰诺直起身板，双臂护着同样瘦弱的狸花猫。

“嘿嘿嘿，你一个瞎子，你知道我是谁吗？你看你，长得像个娘们似的……”胖子继续捏着声音，周围的孩子哄堂大笑。

他们讨厌他。

谁叫这个瞎子，占了自家半条村子的地方，建了这么豪华的庄园？

他打扮得体，住着大房子，而他们穿得破破烂烂，蜗居在泥土房子里。

不可调和的矛盾在帕恩家铲平草坪、赶走他们的时候达到顶峰。

不就是没有陪他玩躲猫猫吗？

但他是帕恩家的少爷，他们不敢随便动他。

直到他们发现，他经常和流浪猫待在一起，便开始拿那些流浪猫来出气。

常年虐待，直到今天，被这个瞎子当场捉住。

“瞎子！”人群里又是一个捏着嗓门的声音，“快睁大你眼睛，看看是谁欺负你啊？！”

这群熊孩子仗着他看不见，把积压多年的不满顺势发泄出来。

“瞎子！”又有一个人说，“你家佣人呢？怎么不来护着他们的宝贝少爷啊？”

“瞎子，你爸妈呢？怎么就只有你一个？哈哈哈！是不是你爸妈嫌弃你是瞎子呀？”

“你好可怜哟，都没人疼你，也没有人愿意护着你，大家都嫌你是累赘!”

嘲讽声不绝于耳。

这个所谓的少爷，瘦弱内向、行单只影，只有他一个人住在那个大别墅里。

连个撑腰的人都没有。

9岁的泰诺咬着牙，将怀里的猫小心翼翼地放在地上，还安抚它一般，轻轻揉了揉它的头。

然后，指尖触到地上一根折断了的树枝——不粗不细，一头很尖。

他将它握住，站起来，朝着笑声的方向，声音因愤怒而颤抖:

“你们，你们这群败类，通通给我道歉！”

熊孩子们纷纷起哄。

“来呀来呀，有本事你打我呀。”一道声音从他左边传来。

泰诺转身冲过去，树杈在空中劈了一道弧线，打了个空。

他踉跄了两步才稳住，身后又响起另一道声音：“我在这呢，来呀来呀。”

他又转身冲过去，树杈再次落空。

他被泥土里一块凸起的石头绊了一下，膝盖跪进泥里。

笑声从四面八方涌过来，像潮水一样。

他站起来，再冲，再扑空。

他被人从背后推了一下，往前踉跄了半步，又被人从侧面拽了一把衣角，他被扯得转了个圈。

他站在那里，浑身是泥，手里还攥着那半截树杈。', 1384, 'chapter_start', FALSE, 'selected', 4.2, '该场景在人物塑造、视角控制和情绪调度上具有可迁移的写作技巧。开篇以黎泱的简约打扮与泰诺的宿醉、食欲不振形成对比，暗示两人关系与阶层差异；随后通过宿醉和梦境自然转入童年回忆，避免了生硬的信息交代。回忆部分以盲人孩子的听觉、触觉为核心构建动作描写（树杈落空、被绊倒、被推搡），生动呈现无助与愤怒，欺凌者的对白层层递进，节奏紧凑。场景虽需一定上下文理解人物关系，但核心冲突和背景可独立感知，对写作者在盲人视角、回忆插入、欺凌场景对白设计等方面有明确参考价值。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 3.5, "distinctiveness": 4.0, "prose_quality": 4.0, "reference_value": 4.5, "scene_completeness": 4.0, "technique_value": 4.5}, "reference_reason": "该场景在人物塑造、视角控制和情绪调度上具有可迁移的写作技巧。开篇以黎泱的简约打扮与泰诺的宿醉、食欲不振形成对比，暗示两人关系与阶层差异；随后通过宿醉和梦境自然转入童年回忆，避免了生硬的信息交代。回忆部分以盲人孩子的听觉、触觉为核心构建动作描写（树杈落空、被绊倒、被推搡），生动呈现无助与愤怒，欺凌者的对白层层递进，节奏紧凑。场景虽需一定上下文理解人物关系，但核心冲突和背景可独立感知，对写作者在盲人视角、回忆插入、欺凌场景对白设计等方面有明确参考价值。", "reference_score": 4.2, "reference_status": "selected"}'::jsonb, '黎泱简约打扮后离开，泰诺宿醉头疼，陷入童年记忆：9岁时因眼盲被村里孩子欺凌，他保护流浪猫，用树枝反击却屡屡落空，被嘲笑“瞎子”“长得像娘们”，孤独无助。', '现实与回忆自然切换，以细腻动作和感官细节展现人物创伤，对比当下与过去，强化情感张力，是刻画人物背景的范本。', '适合学习用回忆插叙揭示人物背景，用动作和对话塑造欺凌场景；避免过度煽情或节奏拖沓。', ARRAY['emotional', 'daily_life']::text[], ARRAY['emotional', 'daily_life']::text[], ARRAY['contrast', 'inner_monologue', 'sensory_detail', 'show_dont_tell']::text[], ARRAY['contrast', 'inner_monologue', 'sensory_detail', 'show_dont_tell']::text[], ARRAY['cinematic', 'dark', 'restrained', 'short_sentence']::text[], ARRAY['cinematic', 'dark', 'restrained', 'short_sentence']::text[], ARRAY['anger', 'grief', 'heartache', 'tension']::text[], ARRAY['anger', 'grief', 'heartache', 'tension']::text[], ARRAY['window', 'door']::text[], ARRAY['window', 'door']::text[], 'reveal', '{"emotion_tags": ["anger", "grief", "heartache", "tension"], "key_images": ["window", "door"], "narrative_func": "reveal", "scene_type": ["emotional", "daily_life"], "style_summary": "现实与回忆自然切换，以细腻动作和感官细节展现人物创伤，对比当下与过去，强化情感张力，是刻画人物背景的范本。", "style_tags": ["cinematic", "dark", "restrained", "short_sentence"], "summary": "黎泱简约打扮后离开，泰诺宿醉头疼，陷入童年记忆：9岁时因眼盲被村里孩子欺凌，他保护流浪猫，用树枝反击却屡屡落空，被嘲笑“瞎子”“长得像娘们”，孤独无助。", "technique": ["contrast", "inner_monologue", "sensory_detail", "show_dont_tell"], "usage_hint": "适合学习用回忆插叙揭示人物背景，用动作和对话塑造欺凌场景；避免过度煽情或节奏拖沓。"}'::jsonb, 'annotated', 'indexed', NULL, 1, TRUE, '2026-10-01T07:15:24.455781+00:00', '2026-10-01T08:01:42.585516+00:00');
