INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at") OVERRIDING SYSTEM VALUE VALUES (899, 44, 29, 19, 19, '黎泱离开的时候，天色已经暗了下来。

她走了大约十分钟，就察觉到身后有人在跟踪自己。

她故意踩断一根枯枝，身后的脚步声顿了一下。

黎泱微微偏头，余光扫过路边的车窗玻璃，倒映出身后二十米处的身影。

她收回目光，继续往前走。突然，加速拐进了一个巷子口。

那男人立马跟了过去。

可当他走进巷子里头，却不见了黎泱的踪影。

巷子里没有灯，两边堆满了杂物。外露的废水管滴落着水滴，在地上形成一滩水渍，招来一群苍蝇。

男人往巷子里走了几步，像是觉察到了什么，回头……

一根铁棍横扫过来，在距离自己10公分的距离刹住。

“你的跟踪技术，还得练练。”黎泱开口嘲讽。

男人的鸭舌帽压得很低，挡住了眉眼，只露出下半张脸。他笑道:

“有没有可能，我是故意被你发现的？”

他缓缓抬头，推了推鸭舌帽，露出完整的一张脸。

在这种环境下，黎泱也不得不承认——

这男人长得真带劲，一种混不吝的劲儿。', 366, 'rule', FALSE, 'selected', 4.1, '该场景在有限篇幅内完成了跟踪—反跟踪—反转—人物登场的完整动作链，利用车窗倒影、枯枝声、巷子环境等细节推进悬念，对白反转（“我是故意被你发现的”）有效制造张力，结尾以外貌评价收束并留下人物关系钩子。动作调度、视角控制、氛围营造和对白节奏均具可迁移性，适合作为跟踪/反跟踪与角色登场类场景的写作参考。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 4.0, "distinctiveness": 3.5, "prose_quality": 3.8, "reference_value": 4.2, "scene_completeness": 4.5, "technique_value": 4.3}, "reference_reason": "该场景在有限篇幅内完成了跟踪—反跟踪—反转—人物登场的完整动作链，利用车窗倒影、枯枝声、巷子环境等细节推进悬念，对白反转（“我是故意被你发现的”）有效制造张力，结尾以外貌评价收束并留下人物关系钩子。动作调度、视角控制、氛围营造和对白节奏均具可迁移性，适合作为跟踪/反跟踪与角色登场类场景的写作参考。", "reference_score": 4.1, "reference_status": "selected"}'::jsonb, '黎泱离开时天色已暗，发现被跟踪。她故意踩断枯枝试探，借车窗玻璃观察，随后加速拐入暗巷。跟踪者追入却不见她踪影，正回头时铁棍横扫而来，在十公分处停住。黎泱嘲讽其跟踪技术，男人却称是故意被发现，并抬头露出脸。黎泱承认他长得带劲，有种混不吝的劲儿。', '以短句和动作细节构建紧张追逐，通过枯枝、车窗倒影、暗巷水滴等感官描写增强画面感。节奏由缓到急，结尾反转与人物外貌描写形成钩子，适合学习用动作展示而非直接叙述。', '适合参考反跟踪场景的节奏控制与感官细节，以及结尾反转制造悬念。避免过度依赖外貌描写打断动作节奏。', ARRAY['action', 'dialogue_conflict', 'mystery']::text[], ARRAY['action', 'dialogue_conflict', 'mystery']::text[], ARRAY['show_dont_tell', 'sensory_detail', 'rhythm_shift', 'twist']::text[], ARRAY['show_dont_tell', 'sensory_detail', 'rhythm_shift', 'twist']::text[], ARRAY['cinematic', 'fast_paced', 'short_sentence', 'colloquial']::text[], ARRAY['cinematic', 'fast_paced', 'short_sentence', 'colloquial']::text[], ARRAY['tension', 'excitement']::text[], ARRAY['tension', 'excitement']::text[], ARRAY['night', 'window']::text[], ARRAY['night', 'window']::text[], 'advance', '{"emotion_tags": ["tension", "excitement"], "key_images": ["night", "window"], "narrative_func": "advance", "scene_type": ["action", "dialogue_conflict", "mystery"], "style_summary": "以短句和动作细节构建紧张追逐，通过枯枝、车窗倒影、暗巷水滴等感官描写增强画面感。节奏由缓到急，结尾反转与人物外貌描写形成钩子，适合学习用动作展示而非直接叙述。", "style_tags": ["cinematic", "fast_paced", "short_sentence", "colloquial"], "summary": "黎泱离开时天色已暗，发现被跟踪。她故意踩断枯枝试探，借车窗玻璃观察，随后加速拐入暗巷。跟踪者追入却不见她踪影，正回头时铁棍横扫而来，在十公分处停住。黎泱嘲讽其跟踪技术，男人却称是故意被发现，并抬头露出脸。黎泱承认他长得带劲，有种混不吝的劲儿。", "technique": ["show_dont_tell", "sensory_detail", "rhythm_shift", "twist"], "usage_hint": "适合参考反跟踪场景的节奏控制与感官细节，以及结尾反转制造悬念。避免过度依赖外貌描写打断动作节奏。"}'::jsonb, 'annotated', 'indexed', NULL, 1, TRUE, '2026-10-01T07:15:24.455781+00:00', '2026-10-01T08:01:42.585516+00:00');
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at") OVERRIDING SYSTEM VALUE VALUES (1060, 44, 190, 128, 128, '第127章 黎泱

五岁的时候，黎泱跟一个小朋友抢玩具，不小心把人推倒在地。

对方的家长凶巴巴地赶来，指着黎泱的鼻子骂：“你妈跟别的男人跑了，你爸呢？！现在没人管你了是吧？没爹养没娘教的野种！”

黎泱跳起来，朝那人的肚子揍了一拳。赶来的黎先勇还穿着一身警服，连忙赔礼道歉，最后带着黎泱离开了帝都，回到小县城。', 149, 'chapter_start', FALSE, 'archived', 2.0, '该场景是一个极简的童年前史片段，以概述方式交代人物背景与性格成因，虽具备完整的事件弧线（冲突—反击—后果），但缺乏场景展开、细节描写、对白节奏和氛围营造，技术迁移价值有限。其写法（用外部辱骂直接揭示家庭创伤、用动作反应展示性格）属于常见套路，对另一位作者的参考意义较弱，更适合作为情节背景而非独立写作范本。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 3.0, "distinctiveness": 1.5, "prose_quality": 2.5, "reference_value": 2.0, "scene_completeness": 3.0, "technique_value": 2.0}, "reference_reason": "该场景是一个极简的童年前史片段，以概述方式交代人物背景与性格成因，虽具备完整的事件弧线（冲突—反击—后果），但缺乏场景展开、细节描写、对白节奏和氛围营造，技术迁移价值有限。其写法（用外部辱骂直接揭示家庭创伤、用动作反应展示性格）属于常见套路，对另一位作者的参考意义较弱，更适合作为情节背景而非独立写作范本。", "reference_score": 2.0, "reference_status": "archived"}'::jsonb, '', '', '', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], '', '{}'::jsonb, 'not_applicable', 'not_applicable', NULL, 1, TRUE, '2026-10-01T07:15:24.455781+00:00', '2026-10-01T08:01:42.585516+00:00');
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at") OVERRIDING SYSTEM VALUE VALUES (953, 44, 83, 63, 63, '第62章 船主是个女人

猩红鎏金的地毯，奢华的丝绒沙发，从大理石栏杆到水晶吊灯，每一处都精雕细琢。

空气里混着雪茄的烟雾、香水的甜腻、香槟酒杯相撞时的轻响。

这里是男人们的主场，每个人都穿着昂贵得体的西装。

偶有几位打扮得珠光宝气的女士，明显只是这些成功男士的挂件。

整个会场，呈沙漏形状，有一圈人围在栏杆那里往下看。

黎泱打量着四周，踩着台阶一步步往下走。

会场的下方，是一个搏击场。

两名拳击选手正在比赛，楼上的人是看客，围成一圈在呐喊。

“你的技术不错嘛。”宋迦木在她身后隔了半步的距离，饶有兴致地打量她。

黎泱回头斜睨他。

“我说易容术。”宋迦木笑得一脸痞气，“我完全认不出你。”

黎泱:“我专业的。”

宋迦木:“以后有需要，找你帮忙化个妆。”

黎泱像看傻子一样，意味深长地看了他一眼:“相信我，你不会想让我帮你化妆的。”

宋迦木:“为什么？”

黎泱耸耸肩没有回答，并收回了视线，重新看向下面的擂台。

宋迦木伸出大长腿，脚尖踢了踢她的脚后跟:“你为什么会在这里？”

黎泱:“是你的准妹夫带我上的船。”

宋迦木:“泰诺·帕恩？”

黎泱:“嗯。”

宋迦木顿了顿，收了几分吊儿郎当的笑意:“那他藏得还挺深的。我就知道这次联姻没那么简单，我那挂名妹妹也算是被分配到一门好婚事。”

黎泱:“为什么？”

宋迦木:“她父母早死，现在整个宋家是她二叔掌权，所以，她是一个空有名头的大小姐，实际上无权无势……”

“谁问你妹了？”黎泱侧目，“我是问你，为什么你说泰诺·帕恩藏得深。”

宋迦木也不扭捏，很自然地切换到另外一个话题:“他们家族总共有十二个儿子，按道理我们应该有更好的选择。但是宋万年……”

他停了一下，改口:“咳咳……我那敬爱的二叔，居然从这些人里面，挑了泰诺·帕恩……

“他从小因为眼睛的原因，被老帕恩先生和他生母塔丽娜夫人嫌弃，被丢在一个废弃的庄园里自生自灭……”

“就这样的人，被我二叔选为联姻对象，一开始我想不明白我那二叔图他什么了，现在看来，他还是有点能耐的。”

黎泱:“帕恩家族是东南亚三大家族之首。别说这游轮了，就算这缅城，有大半边都是他们家的。他再怎么说也是帕恩家族大夫人的儿子，区区一艘游轮，还不至于让帕恩家坐不起。”

黎泱本想告诉宋迦木，泰诺·帕恩住顶层的事情，但最后觉得，还是算了。

出门在外，不能炫富。

宋迦木不置可否，并不急着说话。

他往前半步，拿起了黎泱托盘里的酒，给自己倒了一杯，还斜睨她一眼:“托这么久，手不酸么？”

黎泱给自己换了一只手:“我总得做做样子。”

她没忘记自己是一个走后门……

不对，走前门进来的服务员。

宋迦木端起酒杯，晃了晃杯壁，目光落在琥珀色的液体上:“你的上级这么不专业？”

黎泱:？？？

胡建明？？

宋迦木的一个拐弯，让黎泱摸不着头脑。

黎泱:“跟他有什么关系？”

宋迦木:“你们跨国来缅城，不做背调的么？你们是不是太小看这艘船了？”

“怎么说？”黎泱扭头，认认真真地看向他。

宋迦木:“这艘船，有着全东南亚最大的信息网。”

黎泱的手指在托盘边缘微微收紧了一下。

宋迦木：“你以为这里只是给你看拳赛？在这上输赢的钱都是幌子。真正流通的东西，是坐在牌桌旁边的人，他们的身份、他们的把柄、他们的信息。”

他端起酒杯闻了闻，但没喝，继续说道:

“这艘船就像古代那些权贵开的妓院，有地位的男人聚在一起，你传一句，我递一句，越滚越大，最后整座城的消息都在这艘船上……

“然后被船主拿在他的手里。”

黎泱顺着他的目光看过去。

那些衣冠楚楚的男人，那些珠光宝气的女人，每一个人的背后都连着一条看不见的线，通向这座城市的某个角落。

工厂、地皮、码头、官场、黑市——所有信息交汇在这个金色大厅里，最后都会被某只手收走。

“那有人知道，船主是谁吗？”黎泱问。

宋迦木沉默了一瞬:“不知道。这人很神秘，没有蛛丝马迹。”

他停顿了片刻，补充道:“这个船主可能是个女人吧。”

黎泱:“为什么？”

“因为船主不开妓院。”宋迦木露出混不吝的笑容:“缅城的红灯区产业这么发达，船主却不做那些买卖女人的勾当，只买了一群拳手，在这里设擂台，开赌场……”

黎泱皱了皱眉，她的指尖不经意地抠着托盘边缘，若有所思。

这时，她听到身旁的人在讨论。

路人甲:“赵三爷呢？他不是登船了吗？”

路人乙:“你还没听说吗？昨晚他在餐厅闹事，被赶下船了。”

路人甲:“这么严重？赵三爷在船里的消费一直数一数二，不然只凭他在东南亚的地位，怎么可能住14层的房间。”

宋迦木没在意让人的闲言碎语，他把没喝过的酒杯，原封不动地放回托盘上。

人在江湖浪，他从来不喝来路不明的液体。

他看了黎泱一眼：“你在想什么？”

黎泱把空托盘放在旁边的空位上。

“我在想，”她说，“是时候回去给我家先生沏茶了。”

“啧，来点实话。我们不是搭档吗？”宋迦木倚在栏杆上，笑得吊儿郎当。

他又打量了黎泱一眼，说道:“你易容成这个样子，混进这个会所，为了什么？”

黎泱没有接话，她往栏杆外看下去。

比赛正进入胶着状态，空气里开始弥漫着淡淡的血腥味。

很淡，很淡……只是一个瞬间，便消散在纸醉金迷的铜臭味里。

黎泱:“那要不你先说说看，为什么你会登船？”

宋迦木笑得散漫:“我的身份，是宋迦木，华国宋家独生子，是这艘船的超级vip。”

黎泱:“我不好奇你能登船，我是好奇你为什么想登船，你在查什么？”

“没查什么。”宋迦木轻松地耸耸肩，脸上还是那副吊儿郎当的样子:

“我呀，故地重游罢了。”

黎泱:“故地重游？”

“对。”宋迦木轻笑，“我现在，站的是观众席，可我之前，站的是下面的赛场。”

“你？！”黎泱惊愕道。

她又往下看，赛场上已准备分出胜负了。

一个选手被压制在地板上，他的那张脸早就血肉模糊。

另一个压制的选手也好不到哪里去，负隅顽抗，仅仅吊着一口气罢了。

这种野场的规矩，黎泱是知道的——尽管往死里打，打死不用负责。

堵博在缅城是合法的，拳赛也是合法的，只有杀人是不合法的。

但在拳赛里死了人，那叫遵循比赛规则。

无罪。

如果眼前这个男人说的是真话，那他算得上是从死人堆里爬出来。

“喂喂喂……”宋迦木拿起酒杯轻敲酒瓶，发出的脆响，拉回黎泱的思绪。

“我已经知无不言、言无不尽了，这么有诚意，你倒是说说看，你在打什么算盘？”

黎泱抬眼看着他那双深色的眼眸，思考了片刻才开口:“你再回答我一个问题。”

宋迦木:“你说吧。”

黎泱:“你在船上住几楼？”

“宋家是最高权限的vip，当然住15，就在这会所的下面。”

宋迦木说这话时，勾着唇角，挑起眉尖，大有一副炫富的嘴脸。

可他看着黎泱的神情慢慢变得凝重，便收起大半分笑意:

“怎么了？”

黎泱:“我好像知道，这艘船的船主是谁了。”

宋迦木脸上的笑容尽数褪去:“是谁？”

黎泱:“泰诺·帕恩。”', 2657, 'chapter_start', FALSE, 'selected', 3.8, '该场景在对话节奏、信息分层揭露和结尾反转上具有可迁移的写作参考价值。环境描写与人物动作细节有效烘托氛围，对话自然且能塑造人物性格。虽依赖一定上下文，但核心悬念设置（船主身份）和揭示方式独立可学，适合作为对话驱动悬念的参考样本。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 3.0, "distinctiveness": 3.0, "prose_quality": 3.5, "reference_value": 3.8, "scene_completeness": 4.5, "technique_value": 4.0}, "reference_reason": "该场景在对话节奏、信息分层揭露和结尾反转上具有可迁移的写作参考价值。环境描写与人物动作细节有效烘托氛围，对话自然且能塑造人物性格。虽依赖一定上下文，但核心悬念设置（船主身份）和揭示方式独立可学，适合作为对话驱动悬念的参考样本。", "reference_score": 3.8, "reference_status": "selected"}'::jsonb, '黎泱与宋迦木在游轮会所对话，宋透露这艘船拥有全东南亚最大信息网，船主神秘且可能是个女人。黎泱追问宋登船目的，宋坦言自己曾站在下方拳台。最终黎泱推断出船主是泰诺·帕恩。', '对话层层递进，在闲聊中埋设伏笔与反转，用环境细节烘托奢靡与血腥并存的氛围，人物互动自然，结尾揭示身份极具冲击力。', '适合学习用对话推进悬疑、通过日常闲聊揭示世界观、结尾反转。避免信息倾泻过于直白，需保持人物语气与节奏。', ARRAY['dialogue_conflict', 'mystery', 'investigation']::text[], ARRAY['dialogue_conflict', 'mystery', 'investigation']::text[], ARRAY['foreshadow', 'twist', 'show_dont_tell', 'sensory_detail']::text[], ARRAY['foreshadow', 'twist', 'show_dont_tell', 'sensory_detail']::text[], ARRAY['cinematic', 'colloquial', 'dark', 'fast_paced']::text[], ARRAY['cinematic', 'colloquial', 'dark', 'fast_paced']::text[], ARRAY['tension', 'excitement']::text[], ARRAY['tension', 'excitement']::text[], ARRAY['blood', 'light']::text[], ARRAY['blood', 'light']::text[], 'reveal', '{"emotion_tags": ["tension", "excitement"], "key_images": ["blood", "light"], "narrative_func": "reveal", "scene_type": ["dialogue_conflict", "mystery", "investigation"], "style_summary": "对话层层递进，在闲聊中埋设伏笔与反转，用环境细节烘托奢靡与血腥并存的氛围，人物互动自然，结尾揭示身份极具冲击力。", "style_tags": ["cinematic", "colloquial", "dark", "fast_paced"], "summary": "黎泱与宋迦木在游轮会所对话，宋透露这艘船拥有全东南亚最大信息网，船主神秘且可能是个女人。黎泱追问宋登船目的，宋坦言自己曾站在下方拳台。最终黎泱推断出船主是泰诺·帕恩。", "technique": ["foreshadow", "twist", "show_dont_tell", "sensory_detail"], "usage_hint": "适合学习用对话推进悬疑、通过日常闲聊揭示世界观、结尾反转。避免信息倾泻过于直白，需保持人物语气与节奏。"}'::jsonb, 'annotated', 'indexed', NULL, 1, TRUE, '2026-10-01T07:15:24.455781+00:00', '2026-10-01T08:01:42.585516+00:00');
INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at") OVERRIDING SYSTEM VALUE VALUES (959, 44, 89, 68, 68, '第67章 我爱你

“duang”的一声，黎泱觉得自己的大脑被一口古老的大钟，狠狠地撞了一下。

头嗡嗡嗡地响。

半天，她才从重度耳鸣中反应过来。

敢什么？

爱他？

这是要吓死谁呢？！

可她是金丝雀啊，被困在bling bling鸟笼里的金丝雀。她还能有什么别的答案，只能说:

“当然，芍药当然爱……”

“在这个字上，” 泰诺抢在她把答案说出来的前一秒，给了她一个忠告，“我劝你不要撒谎。”

【我喜欢你】

这种谎言，她平日里说说就算了，就当作是看了一部a片——不真实，但能提取情绪价值和满足某种需求。

但【我爱你】……

泰诺不想他们之间，连这三个字都掺杂着谎言与算计。

如果是谎话，他宁愿她闭嘴。

泰诺的声音听起来好像很平和，但再仔细听听，却是没什么温度。

不是一则温馨提示，是恐吓。

黎泱把“你”字立马吞回肚子里，取而代之的是……

黎泱:“芍药不敢。”

停了两三秒，泰诺继续问:“为什么？”

黎泱有点烦躁。

这金主也太难伺候了。

说敢，就恐吓她，说不敢，又要刨根问底。

黎泱只好给自己找了一个能体现她高情商的说辞:

“芍药很清楚自己的定位，我只是先生豢养的一只金丝雀，能待在先生身边，已经很感恩了。爱很沉重，芍药不会给先生增加心里负担。”

啧啧啧，大家细品，看看说得多好，黎泱差点把自己感动哭了。

可她的感动没有屁点用，她的金主屁点都没感动。

泰诺:“你很清楚你自己的定位？”

“非常清楚。”

黎泱庄重地点点头，又怕他看不见，用力地握了握他的手。

可反手，就被人扣住了。

泰诺:“既然清楚自己的定位，为什么不听我的话？”

看吧，什么爱与不爱，他泰诺·帕恩根本不在乎，他要的是服从。

就是他说的，那种至高无上的掌控感。

黎泱装傻:“我何时不听先生的话了？都说了初吻要留给我的未婚夫。”

泰诺:“除了这个，就没别的吗？”

黎泱:“没有。”

泰诺提醒她:“比方说，我让你别去16楼那个会所，你去了吗？”

“没去。”黎泱斩钉截铁地回答，没半点心虚，心理素质杠杠的。

她想起身，把自己从泰诺的桎梏中抽离。

可泰诺脚尖往前一步，座椅向前，直接把黎泱死死地抵在书桌的边缘，焊死在自己怀里。

泰诺:“确定？要不要仔细想想再回答？”

黎泱垂下眼，看着自己被泰诺扣住的手，那微微蜷缩的手指。

指甲上还残留着易容时没擦干净的哑光粉底。

这些痕迹，此刻在灯光下泛着细碎的白。

但黎泱坚信，没有人会看出端倪。她对自己的易容技术很有信心。

毕竟，她从小跟在身边长大的那位亲奶奶，是他们小镇上，唯一一位殓葬师。

在别的小女生还在偷拿妈妈化妆品涂涂抹抹的时候，8岁的黎泱已经对着尸体帮奶奶打下手了。

10岁她就能熟练地对那些面容残缺的尸体打石膏，帮他们修补容貌。

这份工作不体面，遭人嫌弃。

同学的家长们知道后，都不允许自家的小孩和黎泱玩，更不允许小孩把黎泱带回家。

他们说她晦气。

所以才会吓跑她妈，克死她爸。

但黎泱的奶奶告诉她——活着的人比死了的人，更恐怖。

因为死了的人不会撒谎，但活着的人可以没有一句真话。

“真的没有。”黎泱淡定地回答泰诺的追问。

整个房间，在这简单的四个字之后，都陷入了长时间的沉默。

最后，被泰诺一声嗤笑打破。', 1244, 'chapter_start', FALSE, 'selected', 4.0, '该场景在有限篇幅内完成了一次完整的权力不对等对白博弈：从泰诺逼问“爱不爱”开始，通过打断、威胁、装傻、高情商说辞、动作压制、背景闪回和结尾嗤笑，层层推进冲突并留下悬念。对白节奏紧凑，内心吐槽与外部压迫形成反差，指甲残留粉底、殓葬师背景等细节有效服务于人物塑造与主题（活人撒谎）。虽然语言偏网文风格，但技术层面有明确可迁移的写法：如何用对话中的打断与威胁制造张力，如何用内心独白调节节奏，如何插入背景故事强化动机，以及如何用动作细节暗示隐藏信息。', 'v1.0', 'v1', '{"dimensions": {"context_independence": 3.5, "distinctiveness": 3.5, "prose_quality": 3.5, "reference_value": 4.0, "scene_completeness": 4.5, "technique_value": 4.0}, "reference_reason": "该场景在有限篇幅内完成了一次完整的权力不对等对白博弈：从泰诺逼问“爱不爱”开始，通过打断、威胁、装傻、高情商说辞、动作压制、背景闪回和结尾嗤笑，层层推进冲突并留下悬念。对白节奏紧凑，内心吐槽与外部压迫形成反差，指甲残留粉底、殓葬师背景等细节有效服务于人物塑造与主题（活人撒谎）。虽然语言偏网文风格，但技术层面有明确可迁移的写法：如何用对话中的打断与威胁制造张力，如何用内心独白调节节奏，如何插入背景故事强化动机，以及如何用动作细节暗示隐藏信息。", "reference_score": 4.0, "reference_status": "selected"}'::jsonb, '泰诺逼问黎泱是否爱他，警告“我爱你”不能撒谎。黎泱以金丝雀自居，用高情商话术回避，称不敢爱、清楚定位。泰诺转而质问服从，提及16楼会所，黎泱否认。泰诺逼近钳制，黎泱内心回忆殓葬师奶奶教她易容与识人，坚信伪装无破绽。最终她再次否认，沉默后泰诺嗤笑。', '在对话冲突中穿插内心独白，用短句和动作细节制造张力，通过“爱”与“服从”的错位展现权力关系，并借回忆补充人物背景，节奏张弛有度。', '适合参考如何用对话推进冲突、用内心独白揭示伪装与真实、用动作细节强化压迫感；避免过度依赖内心解释，需保持对话的锋利和留白。', ARRAY['dialogue_conflict', 'emotional', 'romance']::text[], ARRAY['dialogue_conflict', 'emotional', 'romance']::text[], ARRAY['inner_monologue', 'show_dont_tell', 'escalation', 'contrast']::text[], ARRAY['inner_monologue', 'show_dont_tell', 'escalation', 'contrast']::text[], ARRAY['short_sentence', 'colloquial', 'dark', 'restrained', 'fast_paced']::text[], ARRAY['short_sentence', 'colloquial', 'dark', 'restrained', 'fast_paced']::text[], ARRAY['tension', 'fear', 'heartache']::text[], ARRAY['tension', 'fear', 'heartache']::text[], ARRAY['light']::text[], ARRAY['light']::text[], 'conflict', '{"emotion_tags": ["tension", "fear", "heartache"], "key_images": ["light"], "narrative_func": "conflict", "scene_type": ["dialogue_conflict", "emotional", "romance"], "style_summary": "在对话冲突中穿插内心独白，用短句和动作细节制造张力，通过“爱”与“服从”的错位展现权力关系，并借回忆补充人物背景，节奏张弛有度。", "style_tags": ["short_sentence", "colloquial", "dark", "restrained", "fast_paced"], "summary": "泰诺逼问黎泱是否爱他，警告