INSERT INTO scenes ("id", "book_id", "scene_index_in_book", "chapter_start_index", "chapter_end_index", "text", "char_count", "split_reason", "is_cross_chapter", "reference_status", "reference_score", "reference_reason", "reference_prompt_version", "reference_rule_version", "reference_meta_json", "summary", "style_summary", "usage_hint", "scene_type", "scene_type_display", "technique", "technique_display", "style_tags", "style_tags_display", "emotion_tags", "emotion_tags_display", "key_images", "key_images_display", "narrative_func", "meta_json", "annotate_status", "index_status", "error_message", "version", "is_active", "created_at", "updated_at") OVERRIDING SYSTEM VALUE VALUES (971, 44, 101, 75, 75, '另一边，宋迦木刚回到自己房间，就给一位微信名为【乡村旅馆火辣老板娘】的用户，发了两个信息——

